const MANIFEST = {
  "type": "Gallery.MagneticCursor",
  "description": "Physics-based image gallery with magnetic cursor interactions and spring animations",
  "editorElement": {
    "selector": ".magnetic-gallery",
    "displayName": "Magnetic Cursor Gallery",
    "archetype": "container",
    "data": {
      "images": {
        "dataType": "text",
        "displayName": "Image URLs",
        "defaultValue": "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=600,https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=600,https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=600,https://images.unsplash.com/photo-1433086966358-54859d0ed716?w=600,https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=600,https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=600",
        "group": "Content",
        "description": "Comma-separated image URLs"
      },
      "magneticStrength": {
        "dataType": "select",
        "displayName": "Magnetic Strength",
        "defaultValue": "0.15",
        "options": ["0.05", "0.1", "0.15", "0.2", "0.3"],
        "group": "Animation"
      },
      "springDamping": {
        "dataType": "select",
        "displayName": "Spring Damping",
        "defaultValue": "0.7",
        "options": ["0.5", "0.6", "0.7", "0.8", "0.9"],
        "group": "Animation"
      },
      "hoverScale": {
        "dataType": "select",
        "displayName": "Hover Scale",
        "defaultValue": "1.08",
        "options": ["1.02", "1.05", "1.08", "1.12", "1.15"],
        "group": "Animation"
      },
      "transitionSpeed": {
        "dataType": "select",
        "displayName": "Transition Speed (ms)",
        "defaultValue": "400",
        "options": ["200", "300", "400", "500", "600"],
        "group": "Animation"
      },
      "gridColumns": {
        "dataType": "select",
        "displayName": "Grid Columns",
        "defaultValue": "3",
        "options": ["2", "3", "4"],
        "group": "Layout"
      },
      "gridGap": {
        "dataType": "select",
        "displayName": "Grid Gap (px)",
        "defaultValue": "24",
        "options": ["12", "16", "20", "24", "32"],
        "group": "Layout"
      },
      "imageAspectRatio": {
        "dataType": "select",
        "displayName": "Aspect Ratio",
        "defaultValue": "4/3",
        "options": ["1/1", "4/3", "3/2", "16/9"],
        "group": "Layout"
      },
      "borderRadius": {
        "dataType": "select",
        "displayName": "Border Radius (px)",
        "defaultValue": "8",
        "options": ["0", "4", "8", "12", "16"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#F4F4F5",
        "group": "Colors"
      },
      "cardBackground": {
        "dataType": "color",
        "displayName": "Card Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "shadowColor": {
        "dataType": "color",
        "displayName": "Shadow Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "overlayColor": {
        "dataType": "color",
        "displayName": "Overlay Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "showOverlay": {
        "dataType": "booleanValue",
        "displayName": "Show Hover Overlay",
        "defaultValue": "true",
        "group": "Content"
      },
