              style={{
                fontSize: '32px',
                fontWeight: '600',
                color: titleColor,
                margin: 0,
                lineHeight: '1.2',
                flex: 1
              }}
            >
              {productTitle}
            </h1>
            <button
              style={{
                width: '40px',
                height: '40px',
                borderRadius: '50%',
                backgroundColor: accentColor,
                border: 'none',
                cursor: 'pointer',
                color: '#FFFFFF',
                fontSize: '16px',
                flexShrink: 0,
                marginLeft: '16px'
              }}
              aria-label="Share"
            >
              ↗
            </button>
          </div>

          {/* Rating */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              marginBottom: '16px'
            }}
          >
            <div style={{ display: 'flex', gap: '2px' }}>
              {renderStars(productRating)}
            </div>
            <span style={{ fontSize: '14px', color: titleColor, fontWeight: '500' }}>{productRating}/5</span>
            <span style={{ fontSize: '14px', color: textColor }}>|</span>
            <span style={{ fontSize: '14px', color: textColor }}>{reviewCount} review</span>
          </div>

          {/* Price */}
          <div style={{ marginBottom: '8px' }}>
            <span
              style={{
                fontSize: '28px',
                fontWeight: '600',
                color: titleColor
              }}
            >
              {productPrice}
            </span>
          </div>
          <p style={{ fontSize: '13px', color: textColor, margin: '0 0 24px 0' }}>
            Tax included.
          </p>

          {/* Countdown Timer */}
          {showCountdown && (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '16px',
                padding: '16px 20px',
                backgroundColor: cardBackground,
                borderRadius: '8px',
                marginBottom: '20px'
              }}
            >
              <span style={{ fontSize: '14px', fontWeight: '600', color: titleColor }}>Sales end in:</span>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '24px', fontWeight: '600', color: titleColor }}>{countdownHours}</div>
                  <div style={{ fontSize: '10px', color: textColor, textTransform: 'uppercase' }}>Hours</div>
                </div>
                <span style={{ fontSize: '20px', color: textColor }}>:</span>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '24px', fontWeight: '600', color: titleColor }}>{countdownMinutes}</div>
                  <div style={{ fontSize: '10px', color: textColor, textTransform: 'uppercase' }}>Minutes</div>
                </div>
                <span style={{ fontSize: '20px', color: textColor }}>:</span>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: '24px', fontWeight: '600', color: titleColor }}>{countdownSeconds}</div>
                  <div style={{ fontSize: '10px', color: textColor, textTransform: 'uppercase' }}>Seconds</div>
                </div>
              </div>
            </div>
          )}

          {/* Free Shipping Progress */}
          {showFreeShippingBar && (
            <div
              style={{
                padding: '16px 20px',
                border: `1px solid ${borderColor}`,
                borderRadius: '8px',
                marginBottom: '20px'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                <span style={{ fontSize: '14px', color: titleColor }}>
                  Spend <strong>{freeShippingThreshold}</strong> more to reach <strong>Free Shipping</strong>!
                </span>
                <span style={{ fontSize: '13px', color: textColor }}>0%</span>
              </div>
              <div
                style={{
                  height: '4px',
                  backgroundColor: borderColor,
                  borderRadius: '2px',
                  overflow: 'hidden'
                }}
              >
                <div
                  style={{
                    width: '0%',
                    height: '100%',
                    backgroundColor: '#22C55E'
                  }}
                />
              </div>
            </div>
          )}

          {/* Quantity & Actions */}
          <div style={{ marginBottom: '20px' }}>
            <span style={{ fontSize: '13px', color: textColor, display: 'block', marginBottom: '8px' }}>Quantity</span>
            <div style={{ display: 'flex', gap: '12px' }}>
              {/* Quantity Selector */}
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  border: `1px solid ${borderColor}`,
                  borderRadius: '8px',
                  overflow: 'hidden'
                }}
              >
                <span
                  style={{
                    width: '48px',
                    height: '48px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '15px',
                    color: titleColor,
                    fontWeight: '500'
                  }}
                >
                  {quantity}
                </span>
                <div style={{ display: 'flex', flexDirection: 'column', borderLeft: `1px solid ${borderColor}` }}>
                  <button
                    onClick={() => setQuantity(quantity + 1)}
                    style={{
                      width: '32px',
                      height: '24px',
                      border: 'none',
                      backgroundColor: 'transparent',
                      cursor: 'pointer',
                      fontSize: '10px',
                      color: textColor
                    }}
                  >
                    ▲
                  </button>
                  <button
                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                    style={{
                      width: '32px',
                      height: '24px',
                      border: 'none',
                      borderTop: `1px solid ${borderColor}`,
                      backgroundColor: 'transparent',
                      cursor: 'pointer',
                      fontSize: '10px',
                      color: textColor
                    }}
                  >
                    ▼
                  </button>
                </div>
              </div>

              {/* Add to Cart */}
              <button
                style={{
                  flex: 1,
                  padding: '16px 24px',
                  borderRadius: '8px',
                  backgroundColor: accentColor,
                  color: '#FFFFFF',
                  border: 'none',
                  fontSize: '15px',
                  fontWeight: '500',
                  cursor: 'pointer'
                }}
              >
                Add to cart
              </button>

              {/* Buy Now */}
              <button
                style={{
                  flex: 1,
                  padding: '16px 24px',
                  borderRadius: '8px',
                  backgroundColor: backgroundColor,
                  color: titleColor,
                  border: `1px solid ${borderColor}`,
                  fontSize: '15px',
                  fontWeight: '500',
                  cursor: 'pointer'
                }}
              >
                Buy it now
              </button>
            </div>
          </div>

          {/* Pickup Info */}
          <div
            style={{
              display: 'flex',
              alignItems: 'flex-start',
              gap: '12px',
              marginBottom: '20px',
              paddingBottom: '20px',
              borderBottom: `1px solid ${borderColor}`
            }}
          >
            <span style={{ color: '#22C55E', fontSize: '16px' }}>✓</span>
            <div>
              <p style={{ fontSize: '14px', color: titleColor, margin: '0 0 4px 0', fontWeight: '500' }}>
                Pickup available at {pickupLocation}
              </p>
              <p style={{ fontSize: '13px', color: textColor, margin: '0 0 4px 0' }}>
                {pickupTime}
              </p>
              <button
                style={{
                  background: 'none',
                  border: 'none',
                  padding: 0,
                  fontSize: '13px',
                  color: titleColor,
                  textDecoration: 'underline',
                  cursor: 'pointer'
                }}
              >
                View store information
              </button>
            </div>
          </div>

          {/* Add to Compare */}
          <button
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              background: 'none',
              border: 'none',
              padding: '12px 0',
              fontSize: '14px',
              color: textColor,
              cursor: 'pointer',
              marginBottom: '20px'
            }}
          >
            <span>⊞</span> Add to compare
          </button>

          {/* Product Meta */}
          <div
            style={{
              padding: '20px',
              backgroundColor: cardBackground,
              borderRadius: '8px'
            }}
          >
            <div style={{ display: 'flex', marginBottom: '12px' }}>
              <span style={{ width: '100px', fontSize: '13px', color: textColor }}>Availability:</span>
              <span style={{ fontSize: '13px', display: 'flex', alignItems: 'center', gap: '6px' }}>
                <span style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: stockInfo.color }} />
                <span style={{ color: stockInfo.color }}>{stockInfo.text}</span>
              </span>
            </div>
            <div style={{ display: 'flex', marginBottom: '12px' }}>
              <span style={{ width: '100px', fontSize: '13px', color: textColor }}>SKU:</span>
              <span style={{ fontSize: '13px', color: titleColor }}>{sku}</span>
            </div>
            <div style={{ display: 'flex' }}>
              <span style={{ width: '100px', fontSize: '13px', color: textColor }}>Collections:</span>
              <span style={{ fontSize: '13px', color: titleColor, flex: 1 }}>
                {collections.join(', ')}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

