function Component({ config = {} }) {
  const [currentSlide, setCurrentSlide] = React.useState(0);
  const [selectedThumbnail, setSelectedThumbnail] = React.useState(0);
  const [quantity, setQuantity] = React.useState(1);
  const [openAccordion, setOpenAccordion] = React.useState(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const productBrand = config?.productBrand || 'Meridian';
  const productTitle = config?.productTitle || 'Special Edition DSP5200 Digital Active Loudspeaker.';
  const productPrice = config?.productPrice || '13,731.00 NIS';
  const productRating = parseFloat(config?.productRating || '5.0');
  const reviewCount = config?.reviewCount || '1';
  const productDescription = config?.productDescription || 'The additional DSP device...';
  const shortDescription = config?.shortDescription || 'The Special Edition DSP5200 delivers ultimate high-resolution performance.';
  const stockStatus = config?.stockStatus || 'inStock';
  const stockCount = config?.stockCount || '96';

  const highlights = [
    { value: config?.highlight1Value || '3 years', label: config?.highlight1Label || 'Free manufacturers warranty' },
    { value: config?.highlight2Value || '1-5 days', label: config?.highlight2Label || 'Delivery time' }
  ];

  const relatedProduct = {
    title: config?.relatedProductTitle || 'Meridian DSW.2 Digital Active Subwoofer',
    price: config?.relatedProductPrice || '12,116.00 NIS'
  };

  const accordions = [
    { title: config?.accordion1Title || 'Flexible credit available', icon: '💳' },
    { title: config?.accordion2Title || 'Insure your product', icon: '🛡️' },
    { title: config?.accordion3Title || 'Returning an item', icon: '↩️' }
  ];

  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const cardBackground = config?.cardBackground || '#F8FAFC';
  const titleColor = config?.titleColor || '#0F172A';
  const textColor = config?.textColor || '#64748B';
  const accentColor = config?.accentColor || '#EA580C';
  const borderColor = config?.borderColor || '#E2E8F0';

  const totalSlides = 13;
  const thumbnails = Array.from({ length: 8 }, (_, i) => i);

  const renderStars = (rating) => {
    return Array.from({ length: 5 }, (_, i) => (
      <span key={i} style={{ color: i < rating ? accentColor : '#E2E8F0', fontSize: '14px' }}>★</span>
    ));
  };

  const nextSlide = () => setCurrentSlide((prev) => (prev + 1) % totalSlides);
  const prevSlide = () => setCurrentSlide((prev) => (prev - 1 + totalSlides) % totalSlides);

  return (
    <div
      className="product-slider-highlights"
      style={{
        backgroundColor,
        padding: '40px',
        minHeight: '1000px'
      }}
    >
      {/* Breadcrumb */}
      <div style={{ fontSize: '13px', color: textColor, marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '8px' }}>
        <span style={{ cursor: 'pointer' }}>Home</span>
        <span>›</span>
        <span style={{ cursor: 'pointer' }}>Loudspeakers</span>
        <span>›</span>
        <span style={{ color: titleColor }}>{productTitle.substring(0, 30)}...</span>
      </div>

      {/* Main Content */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '48px',
          maxWidth: '1200px',
          margin: '0 auto'
        }}
      >
        {/* Left: Image Gallery */}
        <div>
          {/* Main Image with Navigation */}
          <div
            style={{
              position: 'relative',
              backgroundColor: cardBackground,
              borderRadius: '12px',
              aspectRatio: '4/5',
              marginBottom: '16px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              overflow: 'hidden'
            }}
          >
            {/* Placeholder Speaker */}
            <div
              style={{
                width: '40%',
                height: '80%',
                background: 'linear-gradient(180deg, #F5F5F4 0%, #E7E5E4 100%)',
                borderRadius: '8px',
                position: 'relative',
                boxShadow: '0 20px 40px rgba(0,0,0,0.15)'
              }}
            >
              {/* Speaker drivers */}
              <div style={{ position: 'absolute', top: '15%', left: '50%', transform: 'translateX(-50%)', width: '60%', height: '20%', borderRadius: '50%', backgroundColor: '#1C1917' }} />
              <div style={{ position: 'absolute', top: '40%', left: '50%', transform: 'translateX(-50%)', width: '50%', height: '15%', borderRadius: '50%', backgroundColor: '#1C1917' }} />
              <div style={{ position: 'absolute', top: '60%', left: '50%', transform: 'translateX(-50%)', width: '40%', height: '12%', borderRadius: '50%', backgroundColor: '#1C1917' }} />
            </div>

            {/* Navigation Arrows */}
            <button
              onClick={prevSlide}
              style={{
                position: 'absolute',
                left: '16px',
                top: '50%',
                transform: 'translateY(-50%)',
                width: '40px',
                height: '40px',
                borderRadius: '50%',
                backgroundColor: backgroundColor,
                border: `1px solid ${borderColor}`,
                cursor: 'pointer',
                fontSize: '16px',
                color: textColor,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}
            >
              ‹
            </button>
            <button
              onClick={nextSlide}
              style={{
                position: 'absolute',
                right: '16px',
                top: '50%',
                transform: 'translateY(-50%)',
                width: '40px',
                height: '40px',
                borderRadius: '50%',
                backgroundColor: backgroundColor,
                border: `1px solid ${borderColor}`,
                cursor: 'pointer',
                fontSize: '16px',
                color: textColor,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}
            >
              ›
            </button>

            {/* Slide Counter */}
            <div
              style={{
                position: 'absolute',
                bottom: '16px',
                right: '16px',
                padding: '6px 12px',
                backgroundColor: backgroundColor,
                borderRadius: '4px',
                fontSize: '13px',
                color: textColor
              }}
            >
              {currentSlide + 1} / {totalSlides}
            </div>
          </div>

          {/* Horizontal Scrollable Thumbnails */}
          <div
            style={{
              display: 'flex',
              gap: '12px',
              overflowX: 'auto',
              paddingBottom: '8px',
              scrollbarWidth: 'none'
            }}
          >
            {thumbnails.map((_, index) => (
              <button
                key={index}
                onClick={() => {
                  setSelectedThumbnail(index);
                  setCurrentSlide(index);
                }}
                style={{
                  flexShrink: 0,
                  width: '72px',
                  height: '72px',
                  borderRadius: '8px',
                  border: selectedThumbnail === index ? `2px solid ${titleColor}` : `1px solid ${borderColor}`,
                  backgroundColor: cardBackground,
                  cursor: 'pointer',
                  padding: '8px'
                }}
              >
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    borderRadius: '4px',
                    backgroundColor: '#E7E5E4',
                    opacity: 0.4 + (index * 0.08)
                  }}
                />
              </button>
            ))}
          </div>

          {/* Short Description */}
          <p style={{ fontSize: '16px', color: titleColor, lineHeight: '1.6', marginTop: '24px', marginBottom: '24px' }}>
            {shortDescription}
          </p>

          {/* Feature Highlights */}
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              gap: '1px',
              backgroundColor: borderColor,
              borderTop: `1px solid ${borderColor}`,
              borderBottom: `1px solid ${borderColor}`
            }}
          >
            {highlights.map((highlight, index) => (
              <div
                key={index}
                style={{
                  backgroundColor,
                  padding: '24px',
                  textAlign: 'center'
                }}
              >
                <div style={{ fontSize: '28px', fontWeight: '600', color: titleColor, marginBottom: '8px' }}>
                  {highlight.value}
                </div>
                <div style={{ fontSize: '14px', color: textColor, lineHeight: '1.4' }}>
                  {highlight.label}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Right: Product Info */}
        <div>
          {/* Divider line at top */}
          <div style={{ borderLeft: `1px solid ${borderColor}`, paddingLeft: '48px', height: '100%' }}>
            {/* Brand */}
            <p style={{ fontSize: '14px', color: textColor, margin: '0 0 8px 0' }}>
              {productBrand}
            </p>

            {/* Title */}
            <h1
              style={{
                fontSize: '32px',
                fontWeight: '600',
                color: titleColor,
                margin: '0 0 12px 0',
                lineHeight: '1.2'
              }}
            >
              {productTitle}
            </h1>

            {/* Rating */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '20px' }}>
              <div style={{ display: 'flex' }}>{renderStars(productRating)}</div>
              <span style={{ fontSize: '14px', color: textColor }}>({reviewCount})</span>
            </div>

            {/* Price */}
            <div style={{ fontSize: '28px', fontWeight: '600', color: titleColor, marginBottom: '8px' }}>
              {productPrice}
            </div>
            <p style={{ fontSize: '13px', color: textColor, margin: '0 0 24px 0' }}>Tax included.</p>

            {/* Description */}
            <p style={{ fontSize: '14px', color: textColor, lineHeight: '1.7', marginBottom: '24px' }}>
              {productDescription}
            </p>

            {/* Quantity and Actions */}
            <div style={{ display: 'flex', gap: '12px', marginBottom: '20px' }}>
              {/* Quantity */}
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  border: `1px solid ${borderColor}`,
                  borderRadius: '8px'
                }}
              >
                <button
                  onClick={() => setQuantity(Math.max(1, quantity - 1))}
                  style={{
                    width: '44px',
                    height: '44px',
                    border: 'none',
                    backgroundColor: 'transparent',
                    fontSize: '18px',
                    cursor: 'pointer',
                    color: textColor
                  }}
                >
                  −
                </button>
                <span style={{ width: '32px', textAlign: 'center', fontSize: '15px', color: titleColor }}>{quantity}</span>
                <button
                  onClick={() => setQuantity(quantity + 1)}
                  style={{
                    width: '44px',
                    height: '44px',
                    border: 'none',
                    backgroundColor: 'transparent',
                    fontSize: '18px',
                    cursor: 'pointer',
                    color: textColor
                  }}
                >
                  +
                </button>
              </div>

              {/* Add to Cart */}
              <button
                style={{
                  flex: 1,
                  padding: '14px 24px',
                  borderRadius: '8px',
                  backgroundColor: backgroundColor,
                  color: titleColor,
                  border: `1px solid ${borderColor}`,
                  fontSize: '14px',
                  fontWeight: '500',
                  cursor: 'pointer'
                }}
              >
                Add to cart
              </button>
            </div>

            {/* Buy Now */}
            <button
              style={{
                width: '100%',
                padding: '16px',
                borderRadius: '8px',
                backgroundColor: accentColor,
                color: '#FFFFFF',
                border: 'none',
                fontSize: '15px',
                fontWeight: '500',
                cursor: 'pointer',
                marginBottom: '20px'
              }}
            >
              Buy it now
            </button>

            {/* Stock Status */}
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                marginBottom: '8px'
              }}
            >
              <span style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: '#22C55E' }} />
              <span style={{ fontSize: '14px', color: '#22C55E', fontWeight: '500' }}>
                {stockCount} in stock - Get yours today!
              </span>
            </div>

            {/* Progress bar */}
            <div
              style={{
                height: '4px',
                backgroundColor: '#22C55E',
                borderRadius: '2px',
                marginBottom: '32px'
              }}
            />

            {/* You Might Also Need */}
            <div style={{ marginBottom: '32px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                <h3 style={{ fontSize: '16px', fontWeight: '500', color: titleColor, margin: 0 }}>
                  You might also need...
                </h3>
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button style={{ width: '28px', height: '28px', border: `1px solid ${borderColor}`, borderRadius: '4px', backgroundColor: 'transparent', cursor: 'pointer', color: textColor }}>‹</button>
                  <button style={{ width: '28px', height: '28px', border: `1px solid ${borderColor}`, borderRadius: '4px', backgroundColor: 'transparent', cursor: 'pointer', color: textColor }}>›</button>
                </div>
              </div>

              <div
                style={{
                  display: 'flex',
                  gap: '16px',
                  padding: '16px',
                  border: `1px solid ${borderColor}`,
                  borderRadius: '8px'
                }}
              >
                <div
                  style={{
                    width: '80px',
                    height: '80px',
                    backgroundColor: cardBackground,
                    borderRadius: '4px',
                    flexShrink: 0
                  }}
                />
                <div style={{ flex: 1 }}>
                  <h4 style={{ fontSize: '14px', fontWeight: '500', color: titleColor, margin: '0 0 4px 0' }}>
                    {relatedProduct.title}
                  </h4>
                  <p style={{ fontSize: '14px', color: titleColor, margin: '0 0 8px 0' }}>
                    {relatedProduct.price}
                  </p>
                  <button
                    style={{
                      padding: '6px 16px',
                      borderRadius: '4px',
                      backgroundColor: 'transparent',
                      border: `1px solid ${borderColor}`,
                      fontSize: '13px',
                      color: titleColor,
                      cursor: 'pointer'
                    }}
                  >
                    Add to cart
                  </button>
                </div>
              </div>
            </div>

            {/* Accordions */}
            <div style={{ borderTop: `1px solid ${borderColor}` }}>
              {accordions.map((accordion, index) => (
                <button
                  key={index}
                  onClick={() => setOpenAccordion(openAccordion === index ? null : index)}
                  style={{
                    width: '100%',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '16px 0',
                    background: 'none',
                    border: 'none',
                    borderBottom: `1px solid ${borderColor}`,
                    cursor: 'pointer',
                    fontSize: '14px',
                    color: titleColor
                  }}
                >
                  <span style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <span>{accordion.icon}</span>
                    {accordion.title}
                  </span>
                  <span style={{ transform: openAccordion === index ? 'rotate(180deg)' : 'rotate(0)', transition: 'transform 200ms' }}>▾</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

