            display: 'flex',
            gap: cardGap + 'px',
            overflowX: 'auto',
            overflowY: 'hidden',
            scrollbarWidth: 'none',
            msOverflowStyle: 'none',
            WebkitOverflowScrolling: 'touch',
            paddingLeft: '40px',
            paddingRight: '40px',
            paddingTop: '8px',
            paddingBottom: '8px',
            cursor: enableDrag ? (isDragging ? 'grabbing' : 'grab') : 'default'
          }}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseLeave}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
          {/* Hide scrollbar */}
          <style dangerouslySetInnerHTML={{ __html: `
            .horizontal-scroll-carousel div::-webkit-scrollbar {
              display: none;
            }
          `}} />

          {services.map((service, index) => (
            <div
              key={`${uniqueId}-card-${index}`}
              style={getCardStyle(index)}
              onMouseEnter={() => !isDragging && setHoveredCard(index)}
              onMouseLeave={() => setHoveredCard(null)}
              role="article"
              tabIndex={0}
            >
              {/* Number */}
              <span
                style={{
                  fontSize: '14px',
                  fontWeight: '500',
                  color: numberColor,
                  letterSpacing: '0.05em'
                }}
              >
                {String(index + 1).padStart(2, '0')}
              </span>

              {/* Icon Container */}
              <div
                style={{
                  flex: 1,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
              >
                <span
                  style={{
                    fontSize: '64px',
                    color: iconColor,
                    lineHeight: 1,
                    opacity: hoveredCard === index ? 1 : 0.8,
                    transform: hoveredCard === index ? 'scale(1.1)' : 'scale(1)',
                    transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
                  }}
                >
                  {service.icon}
                </span>
              </div>

              {/* Title */}
              <h3
                style={{
                  fontSize: '18px',
                  fontWeight: '500',
                  color: titleColor,
                  margin: '0 0 16px 0',
                  letterSpacing: '-0.01em',
                  textAlign: 'center'
                }}
              >
                {service.title}
              </h3>

              {/* Arrow Link */}
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'center'
                }}
              >
                <button
                  style={{
                    width: '36px',
                    height: '36px',
                    borderRadius: '50%',
                    backgroundColor: 'transparent',
                    border: 'none',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: arrowColor,
                    fontSize: '18px',
                    transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
                  }}
                  onMouseEnter={(e) => {
                    e.target.style.backgroundColor = `${titleColor}10`;
                    e.target.style.color = titleColor;
                  }}
                  onMouseLeave={(e) => {
                    e.target.style.backgroundColor = 'transparent';
                    e.target.style.color = arrowColor;
                  }}
                  onClick={(e) => e.stopPropagation()}
                  aria-label={`Learn more about ${service.title}`}
                >
                  ↗
                </button>
              </div>
            </div>
          ))}

          {/* Extra padding at end for visual balance */}
          <div style={{ flexShrink: 0, width: '24px' }} />
        </div>

        {/* Navigation Arrows */}
        {showNavArrows && (
          <>
            {/* Left Arrow */}
            <button
              onClick={() => scrollByAmount(-1)}
              style={{
                position: 'absolute',
                left: '8px',
                top: '50%',
                transform: 'translateY(-50%)',
                width: '44px',
                height: '44px',
                borderRadius: '50%',
                backgroundColor: backgroundColor,
                border: `1px solid ${dividerColor}`,
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: titleColor,
                fontSize: '18px',
                transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
                zIndex: 10
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = cardBackgroundColor;
                e.target.style.transform = 'translateY(-50%) scale(1.05)';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = backgroundColor;
                e.target.style.transform = 'translateY(-50%) scale(1)';
              }}
              aria-label="Scroll left"
            >
              ←
            </button>

            {/* Right Arrow */}
            <button
              onClick={() => scrollByAmount(1)}
              style={{
                position: 'absolute',
                right: '8px',
                top: '50%',
                transform: 'translateY(-50%)',
                width: '44px',
                height: '44px',
                borderRadius: '50%',
                backgroundColor: backgroundColor,
                border: `1px solid ${dividerColor}`,
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: titleColor,
                fontSize: '18px',
                transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out',
                zIndex: 10
              }}
              onMouseEnter={(e) => {
                e.target.style.backgroundColor = cardBackgroundColor;
                e.target.style.transform = 'translateY(-50%) scale(1.05)';
              }}
              onMouseLeave={(e) => {
                e.target.style.backgroundColor = backgroundColor;
                e.target.style.transform = 'translateY(-50%) scale(1)';
              }}
              aria-label="Scroll right"
            >
              →
            </button>
          </>
        )}

        {/* Gradient Fades */}
        <div
          style={{
            position: 'absolute',
            left: 0,
            top: 0,
            bottom: 0,
            width: '60px',
            background: `linear-gradient(90deg, ${backgroundColor} 0%, transparent 100%)`,
            pointerEvents: 'none',
            zIndex: 5
          }}
          aria-hidden="true"
        />
        <div
          style={{
            position: 'absolute',
            right: 0,
            top: 0,
            bottom: 0,
            width: '60px',
            background: `linear-gradient(-90deg, ${backgroundColor} 0%, transparent 100%)`,
            pointerEvents: 'none',
            zIndex: 5
          }}
          aria-hidden="true"
        />
      </div>

      {/* Scroll Indicator */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          marginTop: '32px',
          gap: '8px'
        }}
      >
        <span
          style={{
            fontSize: '12px',
            color: labelColor,
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
          }}
        >
          <span style={{ opacity: 0.6 }}>←</span>
          Drag to explore
          <span style={{ opacity: 0.6 }}>→</span>
        </span>
      </div>
    </div>
  );
}

