        'polygon(20% 0%, 80% 0%, 100% 100%, 0% 100%)', // trapezoid
        'polygon(0% 0%, 100% 0%, 80% 100%, 20% 100%)', // reverse trapezoid
        'polygon(10% 10%, 90% 10%, 90% 90%, 10% 90%)' // inset square
      ],
