        </div>
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      className="perspective-stack-gallery"
      style={{
        backgroundColor,
        minHeight: '600px',
        padding: '60px 40px',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
