const MANIFEST = {
  "type": "Interactive.RangeSlider",
  "description": "Dual-handle range slider with magnetic snapping, momentum drag, and value preview",
  "editorElement": {
    "selector": ".range-slider",
    "displayName": "Range Slider",
    "archetype": "container",
    "data": {
