    .split(',')
    .map(url => url.trim());
  const columns = parseInt(config?.columns || '3');
  const gap = parseInt(config?.gap || '16');
  const showCaptions = config?.showCaptions !== false;
  const enableSwipe = config?.enableSwipe !== false;
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const textColor = config?.textColor || '#18181B';
  const overlayColor = config?.overlayColor || '#000000';
  const accentColor = config?.accentColor || '#495057';

  const [lightboxOpen, setLightboxOpen] = React.useState(false);
  const [currentIndex, setCurrentIndex] = React.useState(0);
  const [isZoomed, setIsZoomed] = React.useState(false);
  const [swipeStart, setSwipeStart] = React.useState(null);
  const [swipeOffset, setSwipeOffset] = React.useState(0);

  const lightboxRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const openLightbox = (index) => {
    setCurrentIndex(index);
    setLightboxOpen(true);
    setIsZoomed(false);
    document.body.style.overflow = 'hidden';
  };

  const closeLightbox = () => {
    setLightboxOpen(false);
    setIsZoomed(false);
    setSwipeOffset(0);
    document.body.style.overflow = 'auto';
  };

  const goToNext = () => {
    if (currentIndex < images.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setIsZoomed(false);
      setSwipeOffset(0);
    }
  };

  const goToPrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setIsZoomed(false);
      setSwipeOffset(0);
    }
  };

  const handleKeyDown = (e) => {
    if (!lightboxOpen) return;

    switch (e.key) {
      case 'Escape':
        closeLightbox();
        break;
      case 'ArrowLeft':
        goToPrev();
        break;
      case 'ArrowRight':
        goToNext();
        break;
    }
  };

  React.useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [lightboxOpen, currentIndex]);

  const handleTouchStart = (e) => {
    if (!enableSwipe) return;
    setSwipeStart(e.touches[0].clientX);
  };

  const handleTouchMove = (e) => {
    if (!enableSwipe || !swipeStart) return;
    const diff = e.touches[0].clientX - swipeStart;
    setSwipeOffset(diff);
  };

  const handleTouchEnd = () => {
    if (!enableSwipe) return;

    if (swipeOffset > 100) {
      goToPrev();
    } else if (swipeOffset < -100) {
      goToNext();
    }

    setSwipeStart(null);
    setSwipeOffset(0);
  };

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{
        maxWidth: '1200px',
        margin: '0 auto',
        display: 'grid',
        gridTemplateColumns: `repeat(${columns}, 1fr)`,
        gap: `${gap}px`
      }}>
        {images.map((image, index) => (
          <div
            key={index}
            onClick={() => openLightbox(index)}
            style={{
              position: 'relative',
              aspectRatio: '4/3',
              cursor: 'pointer',
              borderRadius: '8px',
              overflow: 'hidden',
              transition: 'transform 300ms ease-out',
              backgroundColor: `${accentColor}15`
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'scale(1.02)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
            }}
          >
            <img
              src={image}
              alt={`Gallery ${index + 1}`}
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover'
              }}
            />

            {showCaptions && (
              <div style={{
                position: 'absolute',
                bottom: 0,
                left: 0,
                right: 0,
                padding: '12px',
                background: 'linear-gradient(to top, rgba(0,0,0,0.7), transparent)',
                color: '#FFFFFF',
                fontSize: '14px',
                opacity: 0,
                transition: 'opacity 300ms ease-out'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.opacity = '1';
              }}>
                Image {index + 1}
              </div>
            )}
          </div>
        ))}
      </div>

      {lightboxOpen && (
        <div
          ref={lightboxRef}
          onClick={(e) => {
            if (e.target === lightboxRef.current) {
              closeLightbox();
            }
          }}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: `${overlayColor}E6`,
            zIndex: 9999,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            opacity: prefersReducedMotion ? 1 : (lightboxOpen ? 1 : 0),
            animation: prefersReducedMotion ? 'none' : 'fadeIn 300ms ease-out',
            backdropFilter: 'blur(8px)'
          }}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
          <button
            onClick={closeLightbox}
            aria-label="Close lightbox"
            style={{
              position: 'absolute',
              top: '20px',
              right: '20px',
              background: 'rgba(255, 255, 255, 0.2)',
              border: 'none',
              color: '#FFFFFF',
              fontSize: '32px',
              width: '48px',
              height: '48px',
              borderRadius: '50%',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'background 200ms ease-out',
              zIndex: 10
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.background = 'rgba(255, 255, 255, 0.3)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = 'rgba(255, 255, 255, 0.2)';
            }}
          >
            ×
          </button>

          {currentIndex > 0 && (
            <button
              onClick={goToPrev}
              aria-label="Previous image"
              style={{
                position: 'absolute',
                left: '20px',
                top: '50%',
                transform: 'translateY(-50%)',
                background: 'rgba(255, 255, 255, 0.2)',
                border: 'none',
                color: '#FFFFFF',
                fontSize: '32px',
                width: '48px',
                height: '48px',
                borderRadius: '50%',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'background 200ms ease-out',
                zIndex: 10
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = 'rgba(255, 255, 255, 0.3)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = 'rgba(255, 255, 255, 0.2)';
              }}
            >
              ‹
            </button>
          )}

          {currentIndex < images.length - 1 && (
            <button
              onClick={goToNext}
              aria-label="Next image"
              style={{
                position: 'absolute',
                right: '20px',
                top: '50%',
                transform: 'translateY(-50%)',
                background: 'rgba(255, 255, 255, 0.2)',
                border: 'none',
                color: '#FFFFFF',
                fontSize: '32px',
                width: '48px',
                height: '48px',
                borderRadius: '50%',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'background 200ms ease-out',
                zIndex: 10
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = 'rgba(255, 255, 255, 0.3)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = 'rgba(255, 255, 255, 0.2)';
              }}
            >
              ›
            </button>
          )}

          <div style={{
            position: 'relative',
            maxWidth: '90vw',
            maxHeight: '90vh',
            transform: prefersReducedMotion ? 'none' : `translateX(${swipeOffset}px)`,
            transition: swipeOffset === 0 ? 'transform 300ms ease-out' : 'none'
          }}>
            <img
              src={images[currentIndex]}
              alt={`Image ${currentIndex + 1}`}
              onClick={() => setIsZoomed(!isZoomed)}
              style={{
                maxWidth: '100%',
                maxHeight: '90vh',
                objectFit: 'contain',
                cursor: 'zoom-in',
                transform: isZoomed ? 'scale(1.5)' : 'scale(1)',
                transition: 'transform 400ms ease-out',
                borderRadius: '8px'
              }}
            />
          </div>

          <div style={{
            position: 'absolute',
            bottom: '20px',
            left: '50%',
            transform: 'translateX(-50%)',
            color: '#FFFFFF',
            fontSize: '14px',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            padding: '8px 16px',
            borderRadius: '20px',
            backdropFilter: 'blur(8px)'
          }}>
            {currentIndex + 1} / {images.length}
          </div>
        </div>
      )}

      <style jsx>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }

        @media (prefers-reduced-motion: reduce) {
          * {
            animation-duration: 0.01ms !important;
            animation-iteration-count: 1 !important;
            transition-duration: 0.01ms !important;
          }
        }
      `}</style>
    </div>
  );
}

media-beforeafterslider:
const MANIFEST = {
  "type": "Media.BeforeAfterSlider",
  "description": "Before/after image comparison slider with draggable divider",
  "editorElement": {
    "selector": ".before-after-slider",
    "displayName": "Before/After Slider",
    "archetype": "container",
    "data": {
      "beforeImage": {
        "dataType": "text",
        "displayName": "Before Image URL",
        "defaultValue": "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800",
        "group": "Content"
      },
      "afterImage": {
        "dataType": "text",
        "displayName": "After Image URL",
        "defaultValue": "https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800",
        "group": "Content"
      },
      "defaultPosition": {
        "dataType": "select",
        "displayName": "Default Position (%)",
        "defaultValue": "50",
        "options": ["25", "33", "50", "66", "75"],
        "group": "Content"
      },
      "orientation": {
        "dataType": "select",
        "displayName": "Divider Orientation",
        "defaultValue": "vertical",
        "options": ["vertical", "horizontal"],
        "group": "Layout"
      },
      "showLabels": {
        "dataType": "booleanValue",
        "displayName": "Show Before/After Labels",
        "defaultValue": true,
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "dividerColor": {
        "dataType": "color",
        "displayName": "Divider Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "handleColor": {
        "dataType": "color",
        "displayName": "Handle Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const beforeImage = config?.beforeImage || 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800';
  const afterImage = config?.afterImage || 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800';
  const defaultPosition = parseInt(config?.defaultPosition || '50');
  const orientation = config?.orientation || 'vertical';
  const showLabels = config?.showLabels !== false;
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const dividerColor = config?.dividerColor || '#FFFFFF';
  const handleColor = config?.handleColor || '#495057';
  const accentColor = config?.accentColor || '#495057';

  const [position, setPosition] = React.useState(defaultPosition);
  const [isDragging, setIsDragging] = React.useState(false);

  const containerRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const handleMove = (clientX, clientY) => {
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();

    if (orientation === 'vertical') {
      const x = clientX - rect.left;
      const percentage = Math.max(0, Math.min(100, (x / rect.width) * 100));
      setPosition(percentage);
    } else {
      const y = clientY - rect.top;
      const percentage = Math.max(0, Math.min(100, (y / rect.height) * 100));
      setPosition(percentage);
    }
  };

  const handleMouseDown = () => {
    setIsDragging(true);
  };

  const handleMouseMove = (e) => {
    if (!isDragging) return;
    handleMove(e.clientX, e.clientY);
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleTouchMove = (e) => {
    if (!isDragging) return;
    const touch = e.touches[0];
    handleMove(touch.clientX, touch.clientY);
  };

  React.useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      window.addEventListener('touchmove', handleTouchMove);
      window.addEventListener('touchend', handleMouseUp);

      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
        window.removeEventListener('touchmove', handleTouchMove);
        window.removeEventListener('touchend', handleMouseUp);
      };
    }
  }, [isDragging]);

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{ width: '100%', maxWidth: '900px' }}>
        <div
          ref={containerRef}
          style={{
            position: 'relative',
            width: '100%',
            aspectRatio: '16/9',
            overflow: 'hidden',
            borderRadius: '12px',
            cursor: isDragging ? 'grabbing' : 'grab',
            userSelect: 'none',
            boxShadow: '0 8px 24px rgba(0, 0, 0, 0.15)'
          }}
        >
          <img
            src={afterImage}
            alt="After"
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              pointerEvents: 'none',
              userSelect: 'none'
            }}
            draggable={false}
          />

          <div
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              clipPath: orientation === 'vertical'
                ? `inset(0 ${100 - position}% 0 0)`
                : `inset(0 0 ${100 - position}% 0)`,
              transition: isDragging ? 'none' : 'clip-path 150ms ease-out'
            }}
          >
            <img
              src={beforeImage}
              alt="Before"
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                pointerEvents: 'none',
                userSelect: 'none'
              }}
              draggable={false}
            />
          </div>

          <div
            onMouseDown={handleMouseDown}
            onTouchStart={(e) => {
              e.preventDefault();
              setIsDragging(true);
            }}
            style={{
              position: 'absolute',
              ...(orientation === 'vertical' ? {
                left: `${position}%`,
                top: 0,
                bottom: 0,
                width: '4px',
                transform: 'translateX(-50%)',
                cursor: 'ew-resize'
              } : {
                top: `${position}%`,
                left: 0,
                right: 0,
                height: '4px',
                transform: 'translateY(-50%)',
                cursor: 'ns-resize'
              }),
              backgroundColor: dividerColor,
              zIndex: 2,
              boxShadow: '0 0 10px rgba(0, 0, 0, 0.5)',
              transition: isDragging ? 'none' : 'all 150ms ease-out'
            }}
          >
            <div
              style={{
                position: 'absolute',
                ...(orientation === 'vertical' ? {
                  top: '50%',
                  left: '50%',
                  transform: 'translate(-50%, -50%)',
                  width: '48px',
                  height: '48px'
                } : {
                  top: '50%',
                  left: '50%',
                  transform: 'translate(-50%, -50%)',
                  width: '48px',
                  height: '48px'
                }),
                backgroundColor: handleColor,
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
                transition: 'transform 200ms ease-out'
              }}
              onMouseEnter={(e) => {
                if (!isDragging) {
                  e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1.1)';
                }
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1)';
              }}
            >
              <div style={{
                display: 'flex',
                gap: '2px',
                ...(orientation === 'vertical' ? {
                  flexDirection: 'row'
                } : {
                  flexDirection: 'column'
                })
              }}>
                <div style={{
                  width: orientation === 'vertical' ? '3px' : '12px',
                  height: orientation === 'vertical' ? '12px' : '3px',
                  backgroundColor: dividerColor,
                  borderRadius: '2px'
                }} />
                <div style={{
                  width: orientation === 'vertical' ? '3px' : '12px',
                  height: orientation === 'vertical' ? '12px' : '3px',
                  backgroundColor: dividerColor,
                  borderRadius: '2px'
                }} />
              </div>
            </div>
          </div>

          {showLabels && (
            <>
              <div style={{
                position: 'absolute',
                top: '20px',
                left: '20px',
                padding: '8px 16px',
                backgroundColor: 'rgba(0, 0, 0, 0.6)',
                color: '#FFFFFF',
                fontSize: '14px',
                fontWeight: '500',
                borderRadius: '6px',
                backdropFilter: 'blur(8px)',
                opacity: orientation === 'vertical' && position < 20 ? 0 : 1,
                transition: 'opacity 200ms ease-out',
                pointerEvents: 'none'
              }}>
                Before
              </div>

              <div style={{
                position: 'absolute',
                top: '20px',
                right: '20px',
                padding: '8px 16px',
                backgroundColor: 'rgba(0, 0, 0, 0.6)',
                color: '#FFFFFF',
                fontSize: '14px',
                fontWeight: '500',
                borderRadius: '6px',
                backdropFilter: 'blur(8px)',
                opacity: orientation === 'vertical' && position > 80 ? 0 : 1,
                transition: 'opacity 200ms ease-out',
                pointerEvents: 'none'
              }}>
                After
              </div>
            </>
          )}
        </div>

        <div style={{
          marginTop: '24px',
          textAlign: 'center',
          fontSize: '14px',
          color: accentColor
        }}>
          Drag the divider to compare • {Math.round(position)}%
        </div>
      </div>
    </div>
  );
}

