  const [hoveredIndex, setHoveredIndex] = React.useState(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const getRandomRotation = (index) => {
    const seed = index * 12345;
    const random = Math.sin(seed) * 10000;
    const normalized = random - Math.floor(random);
    return (normalized - 0.5) * 2 * maxRotation;
  };

  const getRandomOffset = (index, axis) => {
    const seed = index * (axis === 'x' ? 67890 : 54321);
    const random = Math.sin(seed) * 10000;
    const normalized = random - Math.floor(random);
    return (normalized - 0.5) * 20;
  };

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      padding: '60px 20px',
      fontFamily: '"Caveat", cursive, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{
        maxWidth: '1200px',
        margin: '0 auto',
        display: 'grid',
        gridTemplateColumns: `repeat(${columns}, 1fr)`,
        gap: '60px 40px',
        padding: '20px'
      }}>
        {images.map((image, index) => {
          const rotation = getRandomRotation(index);
          const offsetX = getRandomOffset(index, 'x');
          const offsetY = getRandomOffset(index, 'y');
          const isHovered = hoveredIndex === index;
          const caption = captions[index] || `Photo ${index + 1}`;

          return (
            <div
              key={index}
              onMouseEnter={() => setHoveredIndex(index)}
              onMouseLeave={() => setHoveredIndex(null)}
              style={{
                position: 'relative',
                transform: prefersReducedMotion
                  ? 'none'
                  : isHovered && enableHoverEffect
                  ? 'rotate(0deg) scale(1.05) translateZ(20px)'
                  : `rotate(${rotation}deg) translate(${offsetX}px, ${offsetY}px)`,
                transition: 'all 400ms cubic-bezier(0.34, 1.56, 0.64, 1)',
                cursor: 'pointer',
                transformStyle: 'preserve-3d',
                zIndex: isHovered ? 10 : 1
              }}
            >
              <div style={{
                backgroundColor: polaroidColor,
                padding: '16px',
                paddingBottom: '60px',
                boxShadow: isHovered
                  ? '0 20px 40px rgba(0, 0, 0, 0.3)'
                  : '0 8px 16px rgba(0, 0, 0, 0.15)',
                transition: 'box-shadow 400ms ease-out',
                borderRadius: '4px'
              }}>
                <div style={{
                  position: 'relative',
                  width: '100%',
                  aspectRatio: '1',
                  backgroundColor: `${accentColor}10`,
                  overflow: 'hidden'
                }}>
                  <img
                    src={image}
                    alt={caption}
                    style={{
                      width: '100%',
                      height: '100%',
                      objectFit: 'cover',
                      display: 'block',
                      opacity: prefersReducedMotion ? 1 : (isHovered ? 1 : 0.95),
                      transition: 'opacity 400ms ease-out'
                    }}
                  />

                  {isHovered && (
                    <div style={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      right: 0,
                      bottom: 0,
                      background: 'linear-gradient(135deg, rgba(255,255,255,0.2), transparent)',
                      opacity: prefersReducedMotion ? 0 : 1,
                      animation: prefersReducedMotion ? 'none' : 'shimmer 1s ease-out',
                      pointerEvents: 'none'
                    }} />
                  )}
                </div>

                <div style={{
                  position: 'absolute',
                  bottom: '16px',
                  left: '16px',
                  right: '16px',
                  textAlign: 'center',
                  fontSize: '20px',
                  color: textColor,
                  fontFamily: '"Caveat", cursive',
                  fontWeight: '500',
                  letterSpacing: '0.5px',
                  lineHeight: '1.2',
                  opacity: 0.8
                }}>
                  {caption}
                </div>
              </div>

              <div style={{
                position: 'absolute',
                top: '-10px',
                left: '50%',
                transform: 'translateX(-50%)',
                width: '60px',
                height: '20px',
                background: 'linear-gradient(135deg, rgba(0,0,0,0.1), rgba(0,0,0,0.05))',
                borderRadius: '2px',
                opacity: 0.6
              }} />
            </div>
          );
        })}
      </div>

      <style jsx>{`
        @import url('https://fonts.googleapis.com/css2?family=Caveat:wght@400;500;600&display=swap');

        @keyframes shimmer {
          0% {
            transform: translateX(-100%) translateY(-100%) rotate(45deg);
          }
          100% {
            transform: translateX(100%) translateY(100%) rotate(45deg);
          }
        }

        @media (prefers-reduced-motion: reduce) {
          * {
            animation-duration: 0.01ms !important;
            animation-iteration-count: 1 !important;
            transition-duration: 0.01ms !important;
          }
        }
      `}</style>
    </div>
  );
}

media-diagonalcomparisonslider:
const MANIFEST = {
  "type": "Media.DiagonalComparisonSlider",
  "description": "Image comparison slider that splits diagonally with draggable divider",
  "editorElement": {
    "selector": ".diagonal-comparison-slider",
    "displayName": "Diagonal Comparison Slider",
    "archetype": "container",
    "data": {
      "beforeImage": {
        "dataType": "text",
        "displayName": "Before Image URL",
        "defaultValue": "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200",
        "group": "Content"
      },
      "afterImage": {
        "dataType": "text",
        "displayName": "After Image URL",
        "defaultValue": "https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=1200",
        "group": "Content"
      },
      "diagonalDirection": {
        "dataType": "select",
        "displayName": "Diagonal Direction",
        "defaultValue": "top-left",
        "options": ["top-left", "top-right", "bottom-left", "bottom-right"],
        "group": "Layout"
      },
      "defaultPosition": {
        "dataType": "select",
        "displayName": "Default Position (%)",
        "defaultValue": "50",
        "options": ["25", "33", "50", "66", "75"],
        "group": "Content"
      },
      "showLabels": {
        "dataType": "booleanValue",
        "displayName": "Show Before/After Labels",
        "defaultValue": true,
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "dividerColor": {
        "dataType": "color",
        "displayName": "Divider Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "handleColor": {
        "dataType": "color",
        "displayName": "Handle Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const beforeImage = config?.beforeImage || 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200';
  const afterImage = config?.afterImage || 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=1200';
  const diagonalDirection = config?.diagonalDirection || 'top-left';
  const defaultPosition = parseInt(config?.defaultPosition || '50');
  const showLabels = config?.showLabels !== false;
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const dividerColor = config?.dividerColor || '#FFFFFF';
  const handleColor = config?.handleColor || '#495057';
  const accentColor = config?.accentColor || '#495057';

  const [position, setPosition] = React.useState(defaultPosition);
  const [isDragging, setIsDragging] = React.useState(false);

  const containerRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const getClipPath = () => {
    const pos = position;

    switch (diagonalDirection) {
      case 'top-left':
        return `polygon(0 0, ${pos}% 0, 0 ${pos}%)`;
      case 'top-right':
        return `polygon(${100 - pos}% 0, 100% 0, 100% ${pos}%)`;
      case 'bottom-left':
        return `polygon(0 ${100 - pos}%, ${pos}% 100%, 0 100%)`;
      case 'bottom-right':
        return `polygon(100% ${100 - pos}%, 100% 100%, ${100 - pos}% 100%)`;
      default:
        return `polygon(0 0, ${pos}% 0, 0 ${pos}%)`;
    }
  };

  const getDividerPoints = () => {
    const pos = position;

    switch (diagonalDirection) {
      case 'top-left':
        return { x1: pos, y1: 0, x2: 0, y2: pos };
      case 'top-right':
        return { x1: 100 - pos, y1: 0, x2: 100, y2: pos };
      case 'bottom-left':
        return { x1: 0, y1: 100 - pos, x2: pos, y2: 100 };
      case 'bottom-right':
        return { x1: 100, y1: 100 - pos, x2: 100 - pos, y2: 100 };
      default:
        return { x1: pos, y1: 0, x2: 0, y2: pos };
    }
  };

  const handleMove = (clientX, clientY) => {
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = ((clientX - rect.left) / rect.width) * 100;
    const y = ((clientY - rect.top) / rect.height) * 100;

    let newPosition;
    switch (diagonalDirection) {
      case 'top-left':
        newPosition = (x + y) / 2;
        break;
      case 'top-right':
        newPosition = ((100 - x) + y) / 2;
        break;
      case 'bottom-left':
        newPosition = (x + (100 - y)) / 2;
        break;
      case 'bottom-right':
        newPosition = ((100 - x) + (100 - y)) / 2;
        break;
      default:
        newPosition = (x + y) / 2;
    }

    setPosition(Math.max(0, Math.min(100, newPosition)));
  };

  const handleMouseDown = () => {
    setIsDragging(true);
  };

  const handleMouseMove = (e) => {
    if (!isDragging) return;
    handleMove(e.clientX, e.clientY);
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleTouchMove = (e) => {
    if (!isDragging) return;
    const touch = e.touches[0];
    handleMove(touch.clientX, touch.clientY);
  };

  React.useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      window.addEventListener('touchmove', handleTouchMove);
      window.addEventListener('touchend', handleMouseUp);

      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
        window.removeEventListener('touchmove', handleTouchMove);
        window.removeEventListener('touchend', handleMouseUp);
      };
    }
  }, [isDragging]);

  const dividerPoints = getDividerPoints();
  const handleX = (dividerPoints.x1 + dividerPoints.x2) / 2;
  const handleY = (dividerPoints.y1 + dividerPoints.y2) / 2;

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{ width: '100%', maxWidth: '900px' }}>
        <div
          ref={containerRef}
          style={{
            position: 'relative',
            width: '100%',
            aspectRatio: '16/9',
            overflow: 'hidden',
            borderRadius: '12px',
            cursor: isDragging ? 'grabbing' : 'grab',
            userSelect: 'none',
            boxShadow: '0 8px 24px rgba(0, 0, 0, 0.15)'
          }}
        >
          <img
            src={afterImage}
            alt="After"
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              pointerEvents: 'none',
              userSelect: 'none'
            }}
            draggable={false}
          />

          <div
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              clipPath: getClipPath(),
              transition: isDragging ? 'none' : 'clip-path 150ms ease-out'
            }}
          >
            <img
              src={beforeImage}
              alt="Before"
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                pointerEvents: 'none',
                userSelect: 'none'
              }}
              draggable={false}
            />
          </div>

          <svg
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              pointerEvents: 'none'
            }}
          >
            <line
              x1={`${dividerPoints.x1}%`}
              y1={`${dividerPoints.y1}%`}
              x2={`${dividerPoints.x2}%`}
              y2={`${dividerPoints.y2}%`}
              stroke={dividerColor}
              strokeWidth="4"
              style={{
                filter: 'drop-shadow(0 0 8px rgba(0, 0, 0, 0.5))',
                transition: isDragging ? 'none' : 'all 150ms ease-out'
              }}
            />
          </svg>

          <div
            onMouseDown={handleMouseDown}
            onTouchStart={(e) => {
              e.preventDefault();
              setIsDragging(true);
            }}
            style={{
              position: 'absolute',
              left: `${handleX}%`,
              top: `${handleY}%`,
              transform: 'translate(-50%, -50%)',
              width: '60px',
              height: '60px',
              backgroundColor: handleColor,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              cursor: isDragging ? 'grabbing' : 'grab',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
              transition: isDragging ? 'none' : 'all 150ms ease-out, transform 200ms ease-out',
              zIndex: 10
            }}
            onMouseEnter={(e) => {
              if (!isDragging) {
                e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1.1)';
              }
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1)';
            }}
          >
            <div style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '4px',
              alignItems: 'center'
            }}>
              <div style={{
                width: '20px',
                height: '3px',
                backgroundColor: dividerColor,
                borderRadius: '2px'
              }} />
              <div style={{
                width: '20px',
                height: '3px',
                backgroundColor: dividerColor,
                borderRadius: '2px'
              }} />
            </div>
          </div>

          {showLabels && (
            <>
              <div style={{
                position: 'absolute',
                top: '20px',
                left: diagonalDirection.includes('left') ? '20px' : 'auto',
                right: diagonalDirection.includes('right') ? '20px' : 'auto',
                padding: '8px 16px',
                backgroundColor: 'rgba(0, 0, 0, 0.6)',
                color: '#FFFFFF',
                fontSize: '14px',
                fontWeight: '500',
                borderRadius: '6px',
                backdropFilter: 'blur(8px)',
                pointerEvents: 'none'
              }}>
                Before
              </div>

              <div style={{
                position: 'absolute',
                bottom: '20px',
                right: diagonalDirection.includes('left') ? '20px' : 'auto',
                left: diagonalDirection.includes('right') ? '20px' : 'auto',
                padding: '8px 16px',
                backgroundColor: 'rgba(0, 0, 0, 0.6)',
                color: '#FFFFFF',
                fontSize: '14px',
                fontWeight: '500',
                borderRadius: '6px',
                backdropFilter: 'blur(8px)',
                pointerEvents: 'none'
              }}>
                After
              </div>
            </>
          )}
        </div>

        <div style={{
          marginTop: '24px',
          textAlign: 'center',
          fontSize: '14px',
          color: accentColor
        }}>
          Drag the handle to compare • Direction: {diagonalDirection.replace('-', ' to ')}
        </div>
      </div>
    </div>
  );
}

