            }}
          >
            ›
          </button>

          {/* Thumbnail Navigation */}
          <div style={{
            position: 'absolute',
            bottom: '2rem',
            left: '50%',
            transform: 'translateX(-50%)',
            display: 'flex',
            gap: '0.5rem',
            maxWidth: '90vw',
            overflowX: 'auto',
            padding: '0.5rem'
          }}
          onClick={(e) => e.stopPropagation()}
          >
            {images.map((imageUrl, index) => (
              <button
                key={index}
                onClick={() => setLightboxIndex(index)}
                style={{
                  width: '60px',
                  height: '60px',
                  borderRadius: '4px',
                  border: index === lightboxIndex ? `2px solid ${thumbnailBorder}` : '2px solid transparent',
                  padding: 0,
                  cursor: 'pointer',
                  overflow: 'hidden',
                  opacity: index === lightboxIndex ? 1 : 0.6,
                  transition: 'all 200ms ease-out',
                  flexShrink: 0
                }}
                onMouseEnter={(e) => {
                  if (index !== lightboxIndex) e.currentTarget.style.opacity = 0.8;
                }}
                onMouseLeave={(e) => {
                  if (index !== lightboxIndex) e.currentTarget.style.opacity = 0.6;
                }}
              >
                <img
                  src={imageUrl}
                  alt={`Thumbnail ${index + 1}`}
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover'
                  }}
                />
              </button>
            ))}
          </div>
        </div>
      )}

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }

        @keyframes zoomIn {
          from {
            opacity: 0;
            transform: scale(0.95);
          }
          to {
            opacity: 1;
            transform: scale(1);
          }
        }

        @media (max-width: 768px) {
          .image-gallery > div > div:last-of-type {
            grid-template-columns: repeat(2, 1fr) !important;
          }
        }

        @media (prefers-reduced-motion: reduce) {
          .image-gallery * {
            animation: none !important;
            transition: none !important;
          }
        }
      `}</style>
    </div>
  );
}

