const MANIFEST = {
  "type": "Interactive.FLIPGallery",
  "description": "Image gallery with FLIP technique for smooth grid-to-detail transitions",
  "editorElement": {
    "selector": ".flip-gallery",
    "displayName": "FLIP Gallery",
    "archetype": "container",
    "data": {
      "itemCount": {
        "dataType": "select",
