    { url: "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1920", caption: "Mountain Vista" },
    { url: "https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=1920", caption: "Forest Path" },
    { url: "https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=1920", caption: "Desert Sunset" },
