            opacity: 1
          }}
        />

        {/* Navigation arrows */}
        <button
          onClick={goToPrevious}
          aria-label="Previous image"
          style={{
            position: 'absolute',
            left: '24px',
            top: '50%',
            transform: 'translateY(-50%)',
            backgroundColor: 'rgba(255, 255, 255, 0.1)',
            backdropFilter: 'blur(10px)',
            WebkitBackdropFilter: 'blur(10px)',
            border: 'none',
            borderRadius: '50%',
            width: '48px',
            height: '48px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: controlsColor,
            fontSize: '24px',
            cursor: 'pointer',
            transition: prefersReducedMotion ? 'none' : 'transform 200ms ease-out',
            outline: 'none'
          }}
          onMouseEnter={(e) => {
            if (!prefersReducedMotion) e.currentTarget.style.transform = 'translateY(-50%) scale(1.1)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = 'translateY(-50%) scale(1)';
          }}
          onFocus={(e) => {
            e.currentTarget.style.outline = `2px solid ${accentColor}`;
            e.currentTarget.style.outlineOffset = '2px';
          }}
          onBlur={(e) => {
            e.currentTarget.style.outline = 'none';
          }}
        >
          ‹
        </button>

        <button
          onClick={goToNext}
          aria-label="Next image"
          style={{
            position: 'absolute',
            right: '24px',
            top: '50%',
            transform: 'translateY(-50%)',
            backgroundColor: 'rgba(255, 255, 255, 0.1)',
            backdropFilter: 'blur(10px)',
            WebkitBackdropFilter: 'blur(10px)',
            border: 'none',
            borderRadius: '50%',
            width: '48px',
            height: '48px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: controlsColor,
            fontSize: '24px',
            cursor: 'pointer',
            transition: prefersReducedMotion ? 'none' : 'transform 200ms ease-out',
            outline: 'none'
          }}
          onMouseEnter={(e) => {
            if (!prefersReducedMotion) e.currentTarget.style.transform = 'translateY(-50%) scale(1.1)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = 'translateY(-50%) scale(1)';
          }}
          onFocus={(e) => {
            e.currentTarget.style.outline = `2px solid ${accentColor}`;
            e.currentTarget.style.outlineOffset = '2px';
          }}
          onBlur={(e) => {
            e.currentTarget.style.outline = 'none';
          }}
        >
          ›
        </button>

        {/* Counter */}
        {showCounter && (
          <div
            style={{
              position: 'absolute',
              top: '24px',
              left: '50%',
              transform: 'translateX(-50%)',
              color: controlsColor,
              fontSize: '14px',
              fontWeight: '500',
              backgroundColor: 'rgba(0, 0, 0, 0.5)',
              padding: '8px 16px',
              borderRadius: '20px',
              backdropFilter: 'blur(10px)',
              WebkitBackdropFilter: 'blur(10px)'
            }}
          >
            {currentIndex + 1} / {images.length}
          </div>
        )}

        {/* Caption */}
        {showCaptions && currentImage.caption && (
          <div
            style={{
              position: 'absolute',
              bottom: `${thumbnailSize + 48}px`,
              left: '50%',
              transform: 'translateX(-50%)',
              color: controlsColor,
              fontSize: '16px',
              fontWeight: '400',
              backgroundColor: 'rgba(0, 0, 0, 0.7)',
              padding: '12px 24px',
              borderRadius: '8px',
              backdropFilter: 'blur(10px)',
              WebkitBackdropFilter: 'blur(10px)',
              maxWidth: '80%',
              textAlign: 'center'
            }}
          >
            {currentImage.caption}
          </div>
        )}
      </div>

      {/* Thumbnail strip */}
      <div
        style={{
          backgroundColor: thumbnailStripBackground,
          padding: '16px',
          display: 'flex',
          justifyContent: 'center',
          borderTop: '1px solid rgba(255, 255, 255, 0.1)'
        }}
      >
        <div
          ref={thumbnailStripRef}
          style={{
            display: 'flex',
            gap: `${thumbnailGap}px`,
            overflowX: 'auto',
            maxWidth: '100%',
            padding: '4px',
            scrollbarWidth: 'thin',
            scrollbarColor: `${thumbnailBorderColor} transparent`
          }}
        >
          {images.map((image, index) => (
            <button
              key={index}
              onClick={() => goToIndex(index)}
              aria-label={`Go to image ${index + 1}`}
              aria-current={index === currentIndex ? 'true' : 'false'}
              style={{
                width: `${thumbnailSize}px`,
                height: `${thumbnailSize}px`,
                flexShrink: 0,
                border: index === currentIndex 
                  ? `3px solid ${accentColor}` 
                  : `2px solid ${thumbnailBorderColor}`,
                borderRadius: '6px',
                overflow: 'hidden',
                cursor: 'pointer',
                padding: 0,
                backgroundColor: 'transparent',
                transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out',
                transform: 'translateY(0)',
                opacity: index === currentIndex ? 1 : 0.6,
                outline: 'none'
              }}
              onMouseEnter={(e) => {
                if (!prefersReducedMotion) {
                  e.currentTarget.style.transform = 'translateY(-4px)';
                  e.currentTarget.style.opacity = '1';
                }
              }}
              onMouseLeave={(e) => {
                if (!prefersReducedMotion) {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.opacity = index === currentIndex ? '1' : '0.6';
                }
              }}
              onFocus={(e) => {
                e.currentTarget.style.outline = `2px solid ${accentColor}`;
                e.currentTarget.style.outlineOffset = '2px';
              }}
              onBlur={(e) => {
                e.currentTarget.style.outline = 'none';
              }}
            >
              <img
                src={image.url}
                alt=""
                style={{
                  width: '100%',
                  height: '100%',
                  objectFit: 'cover',
                  display: 'block'
                }}
              />
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

