  // Auto-play
  React.useEffect(() => {
    if (autoPlaySpeed > 0 && !isTransitioning && isReady) {
      const timer = setTimeout(() => {
        setIsTransitioning(true);
        setCurrentSlide(prev => (prev + 1) % totalSlides);
      }, autoPlaySpeed * 1000);
      return () => clearTimeout(timer);
    }
  }, [currentSlide, isTransitioning, autoPlaySpeed, isReady, totalSlides]);

  // Transition animation
  React.useEffect(() => {
    if (!isTransitioning) return;

    const start = Date.now();

    const animate = () => {
      const elapsed = Date.now() - start;
      const progress = Math.min(elapsed / transitionDuration, 1);

      setTransitionProgress(progress);
      setMomentum(Math.sin(progress * Math.PI) * 1.5);

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        setIsTransitioning(false);
        setTransitionProgress(0);
        setMomentum(0);
      }
    };

    animate();
  }, [isTransitioning, transitionDuration]);

  const goToNext = () => {
    if (isTransitioning || !isReady) return;
    setIsTransitioning(true);
    setCurrentSlide(prev => (prev + 1) % totalSlides);
  };

  const goToPrev = () => {
    if (isTransitioning || !isReady) return;
    setIsTransitioning(true);
    setCurrentSlide(prev => (prev - 1 + totalSlides) % totalSlides);
  };

  const counterPos = {
    'bottom-left': { bottom: '20px', left: '20px' },
    'bottom-right': { bottom: '20px', right: '20px' },
    'top-left': { top: '20px', left: '20px' },
    'top-right': { top: '20px', right: '20px' }
  }[config?.counterPosition || 'bottom-left'];

  return (
    <div 
      ref={containerRef}
      className="webgl-carousel-container"
      style={{
        position: 'relative',
        width: '100%',
        height: `${containerHeight}px`,
        backgroundColor: config?.backgroundColor || '#000000',
        overflow: 'hidden'
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          width: '100%',
          height: '100%',
          display: 'block'
        }}
      />

      {loadStatus === 'loading' && (
        <div style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          color: '#FFFFFF',
          fontSize: '14px',
          textAlign: 'center'
        }}>
          <div>Loading images...</div>
          <div style={{ fontSize: '12px', opacity: 0.6, marginTop: '8px' }}>
            Will use fallback if timeout
          </div>
        </div>
      )}

      {config?.showCounter !== false && isReady && (
        <div style={{
          position: 'absolute',
          ...counterPos,
          display: 'flex',
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '8px',
          padding: '10px 14px',
          backgroundColor: config?.counterBackgroundColor || 'rgba(0, 0, 0, 0.6)',
          backdropFilter: 'blur(10px)',
          borderRadius: '6px',
          fontFamily: 'monospace',
          fontSize: '14px',
          fontWeight: '400',
          letterSpacing: '0.05em',
          color: config?.counterTextColor || '#FFFFFF',
          userSelect: 'none',
          zIndex: 10,
          lineHeight: '1'
        }}>
          <span style={{ display: 'inline-block' }}>{String(currentSlide + 1).padStart(2, '0')}</span>
          <span style={{ opacity: 0.5, display: 'inline-block' }}>→</span>
          <span style={{ opacity: 0.5, display: 'inline-block' }}>{String(totalSlides).padStart(2, '0')}</span>
        </div>
      )}

      {config?.showNavButtons !== false && isReady && (
        <>
          <button
            onClick={goToPrev}
            disabled={isTransitioning}
            aria-label="Previous"
            style={{
              position: 'absolute',
              left: '20px',
              top: '50%',
              transform: 'translateY(-50%)',
              width: '48px',
              height: '48px',
              borderRadius: '50%',
              border: 'none',
              backgroundColor: 'rgba(0, 0, 0, 0.6)',
              backdropFilter: 'blur(10px)',
              color: config?.navButtonColor || '#FFFFFF',
              fontSize: '20px',
              cursor: isTransitioning ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 10,
              opacity: isTransitioning ? 0.5 : 1,
              transition: 'all 0.2s ease',
              lineHeight: '1',
              padding: '0'
            }}
          >
            <span style={{ display: 'block', transform: 'translateY(-1px)' }}>←</span>
          </button>

          <button
            onClick={goToNext}
            disabled={isTransitioning}
            aria-label="Next"
            style={{
              position: 'absolute',
              right: '20px',
              top: '50%',
              transform: 'translateY(-50%)',
              width: '48px',
              height: '48px',
              borderRadius: '50%',
              border: 'none',
              backgroundColor: 'rgba(0, 0, 0, 0.6)',
              backdropFilter: 'blur(10px)',
              color: config?.navButtonColor || '#FFFFFF',
              fontSize: '20px',
              cursor: isTransitioning ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 10,
              opacity: isTransitioning ? 0.5 : 1,
              transition: 'all 0.2s ease',
              lineHeight: '1',
              padding: '0'
            }}
          >
            <span style={{ display: 'block', transform: 'translateY(-1px)' }}>→</span>
          </button>
        </>
      )}
    </div>
  );
}

