        "defaultValue": "",
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#0A0A0A",
        "group": "Colors"
      },
      "overlayColor": {
        "dataType": "color",
        "displayName": "Video Overlay Color",
        "defaultValue": "#000000",
        "group": "Colors"
      },
      "overlayOpacity": {
        "dataType": "number",
        "displayName": "Overlay Opacity (0-100)",
        "defaultValue": 60,
        "group": "Colors"
      },
      "titleColor": {
        "dataType": "color",
        "displayName": "Title Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#A3A3A3",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#3B82F6",
        "group": "Colors"
      },
