        ]),
        "group": "Projects",
        "description": "JSON array of 20 projects"
      },

      // Next Section
      "nextSectionTitle": {
        "dataType": "text",
        "displayName": "Next Section Title",
        "defaultValue": "Growth",
        "group": "Next Section"
      },
      "nextSectionLink": {
        "dataType": "text",
        "displayName": "Next Section URL",
        "defaultValue": "/growth/",
        "group": "Next Section"
