      "nextSectionImage": {
        "dataType": "text",
        "displayName": "Next Section Image",
        "defaultValue": "",
        "group": "Next Section"
      },

      // Colors
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Page Background",
        "defaultValue": "#0A0A0A",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#3B82F6",
        "group": "Colors"
      },
      "webglColor": {
        "dataType": "color",
        "displayName": "WebGL Badge Color",
        "defaultValue": "#3B82F6",
        "group": "Colors"
      },
      "javascriptColor": {
        "dataType": "color",
        "displayName": "JavaScript Badge Color",
        "defaultValue": "#10B981",
        "group": "Colors"
      },
      "cssColor": {
        "dataType": "color",
        "displayName": "CSS Badge Color",
        "defaultValue": "#8B5CF6",
