            backgroundColor: uiBackgroundColor,
            border: `1px solid ${uiBorderColor}`,
            borderRadius: '4px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '24px',
            zIndex: 100
          }}
        >
          {characterIcon}
        </div>
      )}

