      <div
        style={{
          position: 'fixed',
          top: isMobile ? '16px' : '20px',
          right: '20px',
          backgroundColor: uiBackgroundColor,
          border: `1px solid ${uiBorderColor}`,
          borderRadius: '4px',
          padding: '8px 16px',
          fontSize: '14px',
          fontWeight: '600',
          color: textColor,
          zIndex: 100
        }}
      >
        {activeCardIndex + 1} / {cards.length}
      </div>

      {/* Info Card */}
      {cards.length > 0 && (
        <div
          style={{
            position: 'fixed',
            left: '50%',
            bottom: '30px',
            transform: 'translateX(-50%)',
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
            width: isMobile ? '260px' : '300px',
            backgroundColor: uiBackgroundColor,
            border: `1px solid ${uiBorderColor}`,
            borderRadius: '4px',
            padding: '3px',
            zIndex: 100
          }}
        >
