          <div>Stage Y: {scrollInfo.y}px</div>
          <div>In View: {scrollInfo.inView ? '✅ YES' : '❌ NO'}</div>
          <div>Stage Top: {scrollInfo.rectTop}px</div>
          <div>Stage Bottom: {scrollInfo.rectBottom}px</div>
          <div>Window H: {scrollInfo.windowHeight}px</div>
          <div>Total H: {totalHeight}px</div>
          <div style={{ marginTop: '8px', color: '#ff0' }}>
            {scrollInfo.inView ? '↕️ SCROLL TO CHANGE CARDS' : '⬇️ SCROLL TO STAGE'}
          </div>
        </div>
      )}

      {/* Character Icon */}
      <div
        style={{
          position: 'fixed',
          top: isMobile ? '16px' : '20px',
          left: '20px',
          width: '40px',
          height: '40px',
          backgroundColor: uiBackgroundColor,
          border: `1px solid ${uiBorderColor}`,
          borderRadius: '4px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '24px',
          zIndex: 100
        }}
      >
        {characterIcon}
      </div>

      {/* Card Counter */}
      <div
        style={{
          position: 'fixed',
          top: isMobile ? '16px' : '20px',
          right: '20px',
          backgroundColor: uiBackgroundColor,
          border: `1px solid ${uiBorderColor}`,
          borderRadius: '4px',
          padding: '8px 16px',
          fontSize: '14px',
          fontWeight: '600',
          color: textColor,
          zIndex: 100
        }}
      >
        {activeCardIndex + 1} / {cards.length}
      </div>

      {/* Info Card */}
      {cards.length > 0 && (
        <div
          style={{
            position: 'fixed',
            left: '50%',
            bottom: '30px',
            transform: 'translateX(-50%)',
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
            width: isMobile ? '260px' : '300px',
            backgroundColor: uiBackgroundColor,
