              alignItems: 'center',
              justifyContent: 'center',
              overflow: 'hidden',
              clipPath: index <= activeCardIndex ? 'inset(0%)' : 'inset(100%)',
              transition: `clip-path ${transitionDuration}ms ease`
            }}
          >
            <img
              src={card.image}
              alt={card.title}
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover'
              }}
            />
          </div>
        ))}
      </div>

      {/* Scroll Progress Bar */}
      <div
        style={{
          position: 'fixed',
          right: '0',
          top: '0',
          width: '3px',
          height: '100vh',
          backgroundColor: 'rgba(0,0,0,0.1)',
