                  }}
                >
                  {showPageTexture && (
                    <div
                      style={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        background: `repeating-linear-gradient(0deg, transparent, transparent 20px, rgba(0,0,0,0.02) 20px, rgba(0,0,0,0.02) 21px)`,
                        pointerEvents: 'none'
                      }}
                    />
                  )}
                </div>

                {/* Page edge curl */}
                <div
                  style={{
                    position: 'absolute',
                    bottom: 0,
                    left: 0,
                    width: '30px',
                    height: '30px',
                    background: `linear-gradient(135deg, transparent 50%, rgba(0,0,0,0.05) 50%)`,
                    borderRadius: `0 0 0 ${borderRadius}px`,
                    pointerEvents: 'none'
                  }}
                />
              </div>
            );
          })}
        </div>

        {/* Right Pages */}
        <div
          style={{
            position: 'absolute',
            left: '50%',
            top: '50%',
            width: `${pageWidth}px`,
            height: `${pageHeight}px`,
            transformStyle: 'preserve-3d',
            transformOrigin: 'left center'
          }}
        >
          {rightPages.map((image, index) => {
            const transform = getPageTransform(index, 'right', rightPages.length);
            const isSelected = selectedPage === `right-${index}`;
            const isHovered = hoveredPage === `right-${index}`;

            return (
              <div
                key={`right-${index}`}
                onClick={() => setSelectedPage(isSelected ? null : `right-${index}`)}
                onMouseEnter={() => setHoveredPage(`right-${index}`)}
                onMouseLeave={() => setHoveredPage(null)}
                style={{
                  position: 'absolute',
                  top: '50%',
                  left: 0,
                  width: `${pageWidth}px`,
                  height: `${pageHeight}px`,
                  marginTop: `-${pageHeight / 2}px`,
                  transformStyle: 'preserve-3d',
                  transformOrigin: 'left center',
                  cursor: 'pointer',
                  opacity: prefersReducedMotion ? 1 : (isInView ? 1 : 0),
                  transform: prefersReducedMotion
                    ? `rotateY(${transform.rotateY}deg) translateZ(${transform.translateZ}px) scale(${transform.scale})`
                    : (isInView
                      ? `rotateY(${transform.rotateY}deg) translateZ(${transform.translateZ}px) translateY(${transform.translateY}px) scale(${transform.scale})`
                      : `rotateY(90deg) translateZ(0) scale(0.8)`
                    ),
                  zIndex: isSelected ? 100 : rightPages.length - index + (isHovered ? 50 : 0),
                  transition: prefersReducedMotion
                    ? 'none'
                    : `transform ${transitionDuration}ms cubic-bezier(0.34, 1.56, 0.64, 1),
                       opacity 500ms ease-out ${(leftPages.length + index) * 80}ms`
                }}
              >
                {/* Page front */}
                <div
                  style={{
                    position: 'absolute',
                    width: '100%',
                    height: '100%',
                    borderRadius: `${borderRadius}px ${borderRadius}px ${borderRadius + 2}px ${borderRadius}px`,
                    overflow: 'hidden',
                    border: `1px solid ${pageBorderColor}`,
                    boxShadow: isSelected
                      ? '0 10px 40px rgba(0,0,0,0.4), 5px 5px 20px rgba(0,0,0,0.2)'
                      : '3px 3px 10px rgba(0,0,0,0.2)',
                    backfaceVisibility: 'hidden'
                  }}
                >
                  <img
                    src={image}
                    alt={`Right page ${index + 1}`}
                    style={{
                      width: '100%',
                      height: '100%',
                      objectFit: 'cover',
                      display: 'block'
                    }}
                  />
                  {showPageTexture && (
                    <div
                      style={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        background: 'linear-gradient(90deg, rgba(0,0,0,0.03) 0%, transparent 20%, transparent 80%, rgba(0,0,0,0.05) 100%)',
                        pointerEvents: 'none'
                      }}
                    />
                  )}
                </div>

                {/* Page back */}
                <div
                  style={{
                    position: 'absolute',
                    width: '100%',
                    height: '100%',
                    borderRadius: `${borderRadius}px`,
                    backgroundColor: pageBackColor,
                    transform: 'rotateY(180deg)',
                    backfaceVisibility: 'hidden',
                    boxShadow: '-3px 3px 10px rgba(0,0,0,0.1)'
                  }}
                />

                {/* Page edge curl */}
                <div
                  style={{
                    position: 'absolute',
                    bottom: 0,
                    right: 0,
                    width: '30px',
                    height: '30px',
                    background: `linear-gradient(-135deg, transparent 50%, rgba(0,0,0,0.05) 50%)`,
                    borderRadius: `0 0 ${borderRadius}px 0`,
                    pointerEvents: 'none'
                  }}
                />
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

