const MANIFEST = {
  "type": "Gallery.RippleRings",
  "description": "A gallery where images are arranged in concentric rings emanating from the center like ripples",
  "editorElement": {
    "selector": ".ripple-rings-gallery",
    "displayName": "Ripple Rings Gallery",
    "archetype": "container",
    "data": {
      "images": {
