        "dataType": "select",
        "displayName": "Ring Spacing",
        "defaultValue": "100",
        "options": ["70", "85", "100", "120", "140"],
        "group": "Layout"
      },
      "outerImageSize": {
        "dataType": "select",
        "displayName": "Outer Image Size",
        "defaultValue": "100",
        "options": ["70", "85", "100", "120", "140"],
        "group": "Layout"
      },
      "pulseAnimation": {
        "dataType": "booleanValue",
        "displayName": "Pulse Animation",
        "defaultValue": true,
        "group": "Animation"
      },
