        "displayName": "Pulse Speed (seconds)",
        "defaultValue": "3",
        "options": ["2", "3", "4", "5"],
        "group": "Animation"
      },
      "rotateRings": {
        "dataType": "booleanValue",
        "displayName": "Rotate Rings",
        "defaultValue": false,
        "group": "Animation"
      },
      "rotationSpeed": {
        "dataType": "select",
        "displayName": "Rotation Speed (seconds)",
        "defaultValue": "30",
        "options": ["15", "20", "30", "45", "60"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#0C0A09",
        "group": "Colors"
      },
