        "defaultValue": "20",
        "options": ["10", "15", "20", "25", "30"],
        "group": "Layout"
      },
      "fanRotation": {
        "dataType": "select",
        "displayName": "Max Fan Rotation (degrees)",
        "defaultValue": "25",
        "options": ["15", "20", "25", "30", "35"],
        "group": "Animation"
      },
      "fanSpread": {
        "dataType": "select",
        "displayName": "Fan Spread Width",
        "defaultValue": "80",
        "options": ["50", "60", "70", "80", "100"],
        "group": "Animation"
      },
