function Component({ config = {} }) {
  const [currentIndex, setCurrentIndex] = React.useState(0);
  const [isHovered, setIsHovered] = React.useState(false);
  const [direction, setDirection] = React.useState(1);
  const containerRef = React.useRef(null);
  const autoPlayRef = React.useRef(null);

  // Configuration - Safe Access
  const backgroundColor = config?.backgroundColor || '#FAFAF9';
  const textColor = config?.textColor || '#1C1917';
  const accentColor = config?.accentColor || '#44403C';
  const duration = parseInt(config?.slideDuration || '6000');
  const autoPlay = config?.autoPlay !== false;
  const layoutReverse = config?.layoutReverse === true;
  const titleFontSize = parseInt(config?.titleFontSize || '64');

  // Parse Slides Data safely
  const slides = React.useMemo(() => {
    try {
      const parsed = JSON.parse(config?.slidesData || '[]');
      return parsed.length ? parsed : [
        {
          title: "Aesthetic Minimal",
          subtitle: "Collection 01",
          description: "Redefining the boundaries of modern living through conscious design.",
          image: "https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?q=80&w=2070&auto=format&fit=crop"
        }
      ];
    } catch (e) {
      return [{ title: "Config Error", subtitle: "Check JSON", description: "Invalid JSON data provided.", image: "" }];
    }
  }, [config?.slidesData]);

  const uniqueId = React.useId();

  // Navigation Logic
  const handleNext = React.useCallback(() => {
    setDirection(1);
    setCurrentIndex((prev) => (prev + 1) % slides.length);
  }, [slides.length]);

  const handlePrev = React.useCallback(() => {
    setDirection(-1);
    setCurrentIndex((prev) => (prev - 1 + slides.length) % slides.length);
  }, [slides.length]);

  const goToSlide = (index) => {
    setDirection(index > currentIndex ? 1 : -1);
    setCurrentIndex(index);
  };

  // AutoPlay Effect
  React.useEffect(() => {
    if (autoPlay && !isHovered) {
      autoPlayRef.current = setInterval(handleNext, duration);
    }
    return () => clearInterval(autoPlayRef.current);
  }, [autoPlay, isHovered, duration, handleNext]);

  // Accessibility: Keyboard Navigation
  React.useEffect(() => {
    const handleKeyDown = (e) => {
      if (!isHovered) return;
      if (e.key === 'ArrowRight') handleNext();
      if (e.key === 'ArrowLeft') handlePrev();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isHovered, handleNext, handlePrev]);

  const currentSlide = slides[currentIndex];

  // Helper for responsive typography
  const isMobile = typeof window !== 'undefined' ? window.innerWidth < 768 : false;

  return (
    <div
      ref={containerRef}
      className="editorial-slider"
      style={{
        width: '100%',
        height: '100%',
        minHeight: '600px',
        backgroundColor: backgroundColor,
        color: textColor,
        display: 'flex',
        flexDirection: isMobile ? 'column-reverse' : (layoutReverse ? 'row-reverse' : 'row'),
        position: 'relative',
        overflow: 'hidden',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif'
      }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* --- CONTENT SECTION --- */}
      <div style={{
        flex: 1,
        padding: isMobile ? '40px 24px' : '80px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        position: 'relative',
        zIndex: 2
      }}>
        {/* Animated Text Container */}
        <div key={`text-${currentIndex}-${uniqueId}`} style={{ maxWidth: '600px' }}>

          {/* Subtitle */}
          <div style={{
            opacity: 0,
            transform: 'translateY(10px)',
            animation: 'fadeInUp 800ms cubic-bezier(0.22, 1, 0.36, 1) forwards',
            animationDelay: '100ms',
            fontSize: '12px',
            textTransform: 'uppercase',
            letterSpacing: '0.2em',
            marginBottom: '24px',
            color: accentColor,
            fontWeight: 500
          }}>
            {currentSlide?.subtitle}
          </div>

          {/* Headline - Split Text Animation Effect */}
          <h1 style={{
            margin: '0 0 32px 0',
            fontSize: isMobile ? '42px' : `${titleFontSize}px`,
            fontFamily: '"Times New Roman", Times, serif', // Editorial feel
            fontWeight: 400,
            lineHeight: 1.1,
            color: textColor,
            overflow: 'hidden'
          }}>
            {currentSlide?.title.split(' ').map((word, i) => (
              <span key={i} style={{ display: 'inline-block', overflow: 'hidden', marginRight: '0.25em', verticalAlign: 'bottom' }}>
                <span style={{
                  display: 'inline-block',
                  opacity: 0,
                  transform: 'translateY(100%)',
                  animation: 'slideUpText 1000ms cubic-bezier(0.16, 1, 0.3, 1) forwards',
                  animationDelay: `${200 + (i * 100)}ms`
                }}>
                  {word}
                </span>
              </span>
            ))}
          </h1>

          {/* Description */}
          <p style={{
            opacity: 0,
            transform: 'translateY(10px)',
            animation: 'fadeInUp 800ms cubic-bezier(0.22, 1, 0.36, 1) forwards',
            animationDelay: '600ms',
            fontSize: '16px',
            lineHeight: 1.6,
            color: `${textColor}CC`, // 80% opacity
            maxWidth: '400px',
            marginBottom: '48px',
            fontWeight: 300
          }}>
            {currentSlide?.description}
          </p>

          {/* CTA Button */}
          <button
            style={{
              opacity: 0,
              animation: 'fadeIn 800ms ease-out forwards',
              animationDelay: '800ms',
              background: 'none',
              border: `1px solid ${textColor}`,
              color: textColor,
              padding: '16px 32px',
              fontSize: '14px',
              textTransform: 'uppercase',
              letterSpacing: '0.1em',
              cursor: 'pointer',
              transition: 'all 300ms ease',
              position: 'relative',
              overflow: 'hidden'
            }}
            onMouseEnter={(e) => {
              e.target.style.backgroundColor = textColor;
              e.target.style.color = backgroundColor;
            }}
            onMouseLeave={(e) => {
              e.target.style.backgroundColor = 'transparent';
              e.target.style.color = textColor;
            }}
          >
            Explore Collection
          </button>
        </div>

        {/* Navigation Controls (Desktop Bottom Left) */}
        <div style={{
          marginTop: 'auto',
          paddingTop: '64px',
          display: 'flex',
          alignItems: 'center',
          gap: '24px'
        }}>
          <button
            onClick={handlePrev}
            aria-label="Previous slide"
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              color: accentColor,
              opacity: 0.7,
              transition: 'opacity 200ms ease',
              padding: '8px'
            }}
            onMouseEnter={e => e.target.style.opacity = 1}
            onMouseLeave={e => e.target.style.opacity = 0.7}
          >
            ←
          </button>

          {/* Pagination Indicators */}
          <div style={{ display: 'flex', gap: '12px' }}>
            {slides.map((_, idx) => (
              <button
                key={idx}
                onClick={() => goToSlide(idx)}
                aria-label={`Go to slide ${idx + 1}`}
                style={{
                  width: '40px',
                  height: '2px',
                  border: 'none',
                  padding: 0,
                  backgroundColor: idx === currentIndex ? textColor : `${textColor}30`,
                  cursor: 'pointer',
                  transition: 'background-color 400ms ease'
                }}
              />
            ))}
          </div>

          <button
            onClick={handleNext}
            aria-label="Next slide"
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              color: accentColor,
              opacity: 0.7,
              transition: 'opacity 200ms ease',
              padding: '8px'
            }}
            onMouseEnter={e => e.target.style.opacity = 1}
            onMouseLeave={e => e.target.style.opacity = 0.7}
          >
            →
          </button>
        </div>
      </div>

      {/* --- IMAGE SECTION --- */}
