const MANIFEST = {
  "type": "Gallery.CylindricalPanorama",
  "description": "3D gallery arranging items on a rotating cylindrical plane.",
  "editorElement": {
    "selector": ".cylinder-gallery",
    "displayName": "Cylindrical Panorama",
    "archetype": "container",
    "data": {
