        "defaultValue": "https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=600,https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=600,https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=600,https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=600,https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=600,https://images.unsplash.com/photo-1501854140884-074cf2b2c3af?w=600",
        "group": "Content"
      },
      "itemWidth": {
        "dataType": "number",
        "displayName": "Item Width (px)",
        "defaultValue": 400,
        "group": "Layout"
      },
      "gap": {
        "dataType": "number",
        "displayName": "Gap (px)",
        "defaultValue": 20,
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const containerRef = React.useRef(null);
  const [rotation, setRotation] = React.useState(0);
  const isDragging = React.useRef(false);
  const lastX = React.useRef(0);
  const velocity = React.useRef(0);
  const requestRef = React.useRef();

  // Config
  const rawImages = config?.images || '';
  const items = React.useMemo(() => rawImages.split(',').map(i => i.trim()).filter(Boolean), [rawImages]);
  const width = parseInt(config?.itemWidth || '400');
  const gap = parseInt(config?.gap || '20');

  // Math: Calculate Radius required to fit all items in a circle
  // Circumference = count * (width + gap)
  // Radius = Circumference / (2 * PI)
  const count = items.length;
  const radius = Math.round((count * (width + gap)) / (2 * Math.PI));
  const anglePerItem = 360 / count;

  // Physics Loop
  React.useEffect(() => {
    const loop = () => {
      if (!isDragging.current && Math.abs(velocity.current) > 0.01) {
        setRotation(prev => prev + velocity.current);
        velocity.current *= 0.95; // Friction
      }
      requestRef.current = requestAnimationFrame(loop);
    };
    loop();
    return () => cancelAnimationFrame(requestRef.current);
  }, []);

  // Drag Handlers
  const handleMouseDown = (e) => {
    isDragging.current = true;
    lastX.current = e.clientX;
    velocity.current = 0;
  };

  const handleMouseMove = (e) => {
    if (!isDragging.current) return;
    const delta = e.clientX - lastX.current;
    lastX.current = e.clientX;

    // Convert px movement to degrees roughly
    const degDelta = (delta / window.innerWidth) * 100;
    setRotation(prev => prev + degDelta);
    velocity.current = degDelta;
  };

  const handleMouseUp = () => {
    isDragging.current = false;
  };

  return (
    <div
      className="cylinder-stage"
      style={{
        width: '100%',
        height: '100%',
        minHeight: '600px',
        backgroundColor: '#111',
        overflow: 'hidden',
        perspective: '2000px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'grab'
      }}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div style={{
        position: 'relative',
        width: width,
        height: Math.round(width * 1.4),
        transformStyle: 'preserve-3d',
        transform: `rotateY(${rotation}deg)`,
        transition: isDragging.current ? 'none' : 'transform 16ms linear' // Optimization
      }}>
        {items.map((src, i) => {
          const theta = i * anglePerItem;

          return (
            <div
              key={i}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                // Rotate to face center, then push out by radius
                transform: `rotateY(${theta}deg) translateZ(${radius}px)`,
                backfaceVisibility: 'hidden', // Hide items when they rotate behind
                backgroundColor: '#222',
                border: '4px solid #fff',
                boxSizing: 'border-box'
              }}
            >
              <div style={{
                width: '100%',
                height: '100%',
                backgroundImage: `url(${src})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                pointerEvents: 'none' // Prevent dragging image ghost
              }} />

              {/* Reflection Effect (Optional Polish) */}
              <div style={{
                position: 'absolute',
                top: '100%',
                left: 0,
                width: '100%',
                height: '50%',
                backgroundImage: `url(${src})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                transform: 'scaleY(-1)',
                opacity: 0.1,
                maskImage: 'linear-gradient(to bottom, rgba(0,0,0,1), rgba(0,0,0,0))',
                WebkitMaskImage: 'linear-gradient(to bottom, rgba(0,0,0,1), rgba(0,0,0,0))',
                pointerEvents: 'none'
              }} />
            </div>
          );
        })}
      </div>
    </div>
  );
}

