const MANIFEST = {
  "type": "Gallery.ZStack",
  "description": "Sticky scroll experience where cards fly forward from a stack.",
  "editorElement": {
    "selector": ".z-stack",
    "displayName": "Z-Axis Scroll Deck",
    "archetype": "container",
    "data": {
      "images": {
        "dataType": "text",
