const MANIFEST = {
  "type": "Gallery.RolodexFile",
  "description": "A technical illustration-style Rolodex file gallery.",
  "editorElement": {
    "selector": ".rolodex-gallery",
    "displayName": "Rolodex File Gallery",
    "archetype": "container",
    "data": {
      "fileData": {
        "dataType": "textarea",
        "displayName": "File Data (JSON)",
        "defaultValue": "[\n  { \"id\": \"010\", \"label\": \"O\", \"isDivider\": true },\n  { \"id\": \"94\", \"label\": \"oil lamp\" },\n  { \"id\": \"96\", \"label\": \"pants\" },\n  { \"id\": \"98\", \"label\": \"plant 003\" },\n  { \"id\": \"012\", \"label\": \"P\", \"isDivider\": true },\n  { \"id\": \"100\", \"label\": \"phisher\" },\n  { \"id\": \"102\", \"label\": \"pencile\" },\n  { \"id\": \"104\", \"label\": \"quiet\" },\n  { \"id\": \"005\", \"label\": \"Q\", \"isDivider\": true },\n  { \"id\": \"106\", \"label\": \"questions\" },\n  { \"id\": \"108\", \"label\": \"quit\" },\n  { \"id\": \"002\", \"label\": \"R\", \"isDivider\": true },\n  { \"id\": \"112\", \"label\": \"rum\" },\n  { \"id\": \"114\", \"label\": \"rain\" }\n]",
        "group": "Content",
        "description": "Array of objects with 'id', 'label', and optional 'isDivider'."
      },
      "bottomLabel": {
        "dataType": "text",
        "displayName": "Bottom Label",
        "defaultValue": "sam's secret files",
        "group": "Content"
      },
      "animationSpeed": {
        "dataType": "select",
        "displayName": "Animation Speed",
        "defaultValue": "fast",
        "options": ["fast", "medium", "slow"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#EAEAEA",
        "group": "Colors"
      },
      "cardColor": {
        "dataType": "color",
        "displayName": "Card Fill Color",
        "defaultValue": "#D6D6D6",
        "group": "Colors"
      },
      "lineColor": {
        "dataType": "color",
        "displayName": "Line/Text Color",
        "defaultValue": "#000000",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Label Accent Color",
        "defaultValue": "#FDFDBE",
        "group": "Colors"
      }
    }
  }
};

function Component({ config = {} }) {
  const [activeIndex, setActiveIndex] = React.useState(0);

  const data = React.useMemo(() => {
    try {
      return JSON.parse(config?.fileData || '[]');
    } catch (e) {
      return [];
    }
  }, [config?.fileData]);

  const bottomLabel = config?.bottomLabel || "sam's secret files";
  const bgColor = config?.backgroundColor || '#EAEAEA';
  const cardColor = config?.cardColor || '#D6D6D6';
  const lineColor = config?.lineColor || '#000000';
  const accentColor = config?.accentColor || '#FDFDBE';

  const transition = React.useMemo(() => {
    const speeds = { fast: '200ms', medium: '400ms', slow: '600ms' };
    return `all ${speeds[config?.animationSpeed || 'fast']} ease-in-out`;
  }, [config?.animationSpeed]);

  const handleCardClick = (index) => {
    setActiveIndex(index);
  };

  if (data.length === 0) {
    return (
      <div style={{ 
        backgroundColor: bgColor, color: lineColor, 
        height: '400px', display: 'flex', alignItems: 'center', justifyContent: 'center',
        fontFamily: "'Courier New', monospace"
      }}>
        Invalid or empty data.
      </div>
    );
  }

  return (
    <div className="rolodex-gallery" style={{
      backgroundColor: bgColor,
      color: lineColor,
      padding: '40px',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '500px',
      fontFamily: "'Courier New', monospace",
      overflow: 'hidden'
    }}>
      {/* Main Rolodex Container */}
      <div style={{
        position: 'relative',
        width: '100%',
        maxWidth: '600px',
        height: '400px',
        border: `2px solid ${lineColor}`,
        backgroundColor: bgColor,
        borderRadius: '4px',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'flex-end',
        paddingBottom: '20px',
        boxSizing: 'border-box'
      }}>
        {/* Card Stack */}
        <div style={{
          position: 'relative',
          width: '90%',
          height: '300px'
        }}>
          {data.map((item, index) => {
            const isActive = index === activeIndex;
            const distanceFromActive = index - activeIndex;

            // Calculate stacking
            let zIndex = data.length - Math.abs(distanceFromActive);
            let translateY = distanceFromActive * -25; // 25px overlap per card
            let scale = 1 - (Math.abs(distanceFromActive) * 0.02);

            if (isActive) {
              zIndex = data.length + 1;
              translateY = 20; // Pop up slightly
              scale = 1.02;
            }

            const isDivider = item.isDivider;

            return (
              <div
                key={item.id}
                onClick={() => handleCardClick(index)}
                style={{
                  position: 'absolute',
                  bottom: 0,
                  left: '50%',
                  transform: `translateX(-50%) translateY(${translateY}px) scale(${scale})`,
                  width: isDivider ? '95%' : '90%',
                  height: '200px',
                  backgroundColor: cardColor,
                  border: `2px solid ${lineColor}`,
                  borderRadius: '8px 8px 0 0',
                  zIndex: zIndex,
                  transition: transition,
                  cursor: 'pointer',
                  display: 'flex',
                  flexDirection: 'column',
                  boxSizing: 'border-box'
                }}
              >
                {/* Tab */}
                <div style={{
                  height: '40px',
                  borderBottom: `2px solid ${lineColor}`,
                  display: 'flex',
                  alignItems: 'center',
                  padding: '0 16px',
                  fontWeight: 'bold',
                  backgroundColor: isDivider ? lineColor : 'transparent',
                  color: isDivider ? bgColor : lineColor,
                  justifyContent: isDivider ? 'space-between' : 'flex-start'
                }}>
                  <span>{item.id}</span>
                  {isDivider && <span>{item.label}</span>}
                </div>

                {/* Content */}
                {!isDivider && (
                  <div style={{
                    flex: 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '1.2rem'
                  }}>
                    {item.label}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Bottom Label */}
      <div style={{
        marginTop: '20px',
        padding: '8px 16px',
        backgroundColor: accentColor,
        border: `2px solid ${lineColor}`,
        borderRadius: '20px',
        fontWeight: 'bold'
      }}>
        {bottomLabel}
      </div>
    </div>
  );
}

