                step.isOutput ? (
                  <div key={idx} style={s.outputCard}>
                    {showStepNumbers && <div style={s.outputNumber}>{step.num}</div>}
                    <span style={s.outputLabel}>{step.label}</span>
                    <div style={s.outputValues}>
                      <div style={s.outputItem}>
                        <span style={s.outputItemLabel}>W:</span>
                        <span style={s.outputValue}>{step.width}</span>
                      </div>
                      <div style={s.outputItem}>
                        <span style={s.outputItemLabel}>H:</span>
                        <span style={s.outputValue}>{step.height}</span>
                      </div>
                    </div>
                  </div>
                ) : (
                  <div key={idx} style={{...s.stepCard, ...(idx % 2 === 0 ? s.stepBg1 : s.stepBg2)}}>
                    {showStepNumbers && <div style={s.stepNumber}>{step.num}</div>}
                    <span style={s.stepLabel}>{step.label}</span>
                    <span style={s.stepValue}>{step.value}</span>
