            <div style={s.outputCard}>
              <div style={s.outputHeader}>// Output values</div>
              <div style={s.outputGrid}>
                <div style={s.outputItem}>
                  <span style={s.outputLabel}>width:</span>
                  <span style={s.outputValue}>{outputWidth}</span>
                </div>
                <div style={s.outputItem}>
                  <span style={s.outputLabel}>height:</span>
                  <span style={s.outputValue}>{outputHeight}</span>
                </div>
              </div>
            </div>
          </div>
        );

      case 'dashboard-tiles':
        return (
          <div style={s.container}>
            <div style={s.tilesGrid}>
              {steps.filter(s => !s.isOutput).map((step, idx) => (
                <div key={idx} style={s.tile}>
                  {showStepNumbers && <div style={s.tileNumber}>{step.num}</div>}
                  <div style={s.tileLabel}>{step.label}</div>
                  <div style={s.tileValue}>{step.value}</div>
                </div>
              ))}
              <div style={s.outputTile}>
                <div style={s.outputHeader}>
                  {showStepNumbers && <div style={s.outputNumber}>6</div>}
                  <span style={s.outputLabel}>Output</span>
