          <div style={s.container}>
            <div style={s.meta}>
              <span style={s.metaTag}>ID: {ruleId}</span>
              <span style={s.metaTag}>{ruleCategory}</span>
              <span style={s.metaTag}>{ruleElement}</span>
              <span style={s.metaTag}>{ruleStatus}</span>
            </div>
            <div style={s.stepsContainer}>
              {steps.map((step, idx) => (
                <div key={idx} style={step.isOutput ? s.outputCard : s.stepCard}>
