                    <div>
                      <div style={s.outputLabel}>Output Width</div>
                      <div style={s.outputValue}>{step.width}</div>
                    </div>
                    <div>
                      <div style={s.outputLabel}>Output Height</div>
                      <div style={s.outputValue}>{step.height}</div>
                    </div>
