                    <span></span>
                  </div>
                )
              ))}
            </div>
          </div>
        );

      case 'portfolio-bold':
        return (
          <div style={s.container}>
            <div style={s.meta}>
              <div style={s.metaItem}>
                <span style={s.metaLabel}>Rule ID</span>
                <span style={s.metaValue}>{ruleId}</span>
              </div>
              <div style={s.metaItem}>
                <span style={s.metaLabel}>Category</span>
                <span style={s.metaValue}>{ruleCategory}</span>
              </div>
              <div style={s.metaItem}>
                <span style={s.metaLabel}>Status</span>
                <span style={s.metaValue}>{ruleStatus}</span>
              </div>
            </div>
