              {steps.filter(st => !st.isOutput).map((step, idx) => (
                <div key={idx} style={s.stepCard}>
                  <span style={s.stepNumber}>{showStepNumbers ? `[${step.num}]` : ''}</span>
                  <span style={s.stepLabel}>{step.label}</span>
                  <span style={s.stepValue}>{step.value}</span>
