                  <span style={s.outputLabel}>Width</span>
                  <span style={s.outputValue}>{outputWidth}</span>
                </div>
                <div style={s.outputItem}>
                  <span style={s.outputLabel}>Height</span>
                  <span style={s.outputValue}>{outputHeight}</span>
                </div>
              </div>
            </div>
          </div>
        );

      case 'specs-minimal':
        return (
          <div style={s.container}>
            <div style={s.stepsContainer}>
              {steps.filter(st => !st.isOutput).map((step, idx) => (
                <div key={idx} style={s.stepCard}>
                  <span style={s.stepLabel}>{showStepNumbers ? `[${step.num}] ` : ''}{step.label}</span>
                  <span style={s.stepValue}>{step.value}</span>
                </div>
              ))}
              <div style={s.outputCard}>
                <span style={s.outputLabel}>Output</span>
                <div style={s.outputValues}>
                  <span>
                    <span style={s.outputValueLabel}>W: </span>
                    <span style={s.outputValue}>{outputWidth}</span>
                  </span>
                  <span>
                    <span style={s.outputValueLabel}>H: </span>
                    <span style={s.outputValue}>{outputHeight}</span>
                  </span>
                </div>
              </div>
            </div>
          </div>
        );

      case 'pricing-stack':
        return (
          <div style={s.container}>
            <div style={s.stepsContainer}>
              {steps.filter(st => !st.isOutput).map((step, idx) => (
                <div key={idx} style={s.stepCard}>
                  <span style={s.stepLabel}>{showStepNumbers ? `Step ${step.num}: ` : ''}{step.label}</span>
                  <span style={s.stepValue}>{step.value}</span>
                </div>
              ))}
            </div>
            <div style={s.outputCard}>
              <div style={s.outputItem}>
                <span style={s.outputLabel}>Output Width</span>
                <span style={s.outputValue}>{outputWidth}</span>
              </div>
              <div style={s.outputItem}>
                <span style={s.outputLabel}>Output Height</span>
                <span style={s.outputValue}>{outputHeight}</span>
              </div>
            </div>
          </div>
        );

      case 'metrics-dashboard':
        return (
          <div style={s.container}>
            <div style={s.metricsRow}>
              <div style={s.metricCard}>
                <div style={s.metricHeader}>
                  <span style={s.metricName}>Category</span>
                  <span style={{...s.badge, ...s.badgeNeutral}}>info</span>
                </div>
                <span style={s.metricValueSmall}>{ruleCategory}</span>
              </div>
              <div style={s.metricCard}>
                <div style={s.metricHeader}>
                  <span style={s.metricName}>Element</span>
                  <span style={{...s.badge, ...s.badgeUp}}>↑ active</span>
                </div>
                <span style={s.metricValueSmall}>{ruleElement}</span>
              </div>
              <div style={s.metricCard}>
                <div style={s.metricHeader}>
                  <span style={s.metricName}>Condition</span>
                  <span style={{...s.badge, ...s.badgeNeutral}}>0%</span>
                </div>
                <span style={s.metricValueSmall}>{condition.slice(0, 15)}...</span>
              </div>
            </div>
            <div style={s.stepsContainer}>
              {steps.filter(st => !st.isOutput).map((step, idx) => (
                <div key={idx} style={s.stepCard}>
                  <div style={s.stepLabel}>{showStepNumbers ? `[${step.num}] ` : ''}{step.label}</div>
                  <div style={s.stepValue}>{step.value}</div>
                </div>
              ))}
              <div style={s.outputCard}>
                <div style={s.outputHeader}>
                  <span style={s.outputBadge}>OUTPUT</span>
                  <span style={s.outputLabel}>Final Values</span>
                </div>
                <div style={s.outputGrid}>
                  <div style={s.outputItem}>
                    <div style={s.outputItemLabel}>Width</div>
                    <div style={s.outputValue}>{outputWidth}</div>
                  </div>
                  <div style={s.outputItem}>
                    <div style={s.outputItemLabel}>Height</div>
                    <div style={s.outputValue}>{outputHeight}</div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        );

      default: // modern-cards, minimal-lines
        return (
          <div style={s.container}>
            {s.meta && (
              <div style={s.meta}>
                {['ID', 'Category', 'Element', 'Status'].map((label, idx) => (
                  <div key={idx} style={s.metaItem || {}}>
                    <span style={s.metaLabel}>{label}</span>
                    <span style={s.metaValue}>
                      {label === 'ID' ? ruleId : 
                       label === 'Category' ? ruleCategory :
                       label === 'Element' ? ruleElement : ruleStatus}
                    </span>
                  </div>
                ))}
              </div>
            )}
            <div style={s.stepsContainer}>
              {steps.map((step, idx) => (
                <div key={idx} style={step.isOutput ? s.outputCard : s.stepCard}>
                  {showStepNumbers && (
                    preset === 'minimal-lines' ? (
                      <span style={s.stepNumber}>[{step.num}]</span>
                    ) : (
                      <div style={s.stepNumber}>{step.num}</div>
                    )
                  )}
                  <div style={s.stepContent}>
                    <div style={s.stepLabel}>{step.label}</div>
                    {step.isOutput ? (
                      <div style={s.outputGrid}>
                        <div style={s.outputItem}>
                          <div style={s.outputLabel}>Width</div>
                          <div style={s.outputValue}>{step.width}</div>
                        </div>
                        <div style={s.outputItem}>
                          <div style={s.outputLabel}>Height</div>
                          <div style={s.outputValue}>{step.height}</div>
                        </div>
                      </div>
                    ) : (
                      <div style={s.stepValue}>{step.value}</div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
    }
  };

  // ═══════════════════════════════════════════════════════════════
  // MAIN RENDER
  // ═══════════════════════════════════════════════════════════════

  return (
    <div 
      className="rule-accordion-showcase"
      style={{
        fontFamily,
        fontSize,
        fontWeight,
        color: textPrimary,
        lineHeight: 1.5,
        ...styles.container,
      }}
    >
      {/* Outer Row (Collapsed State) */}
      <div
        onClick={() => setIsExpanded(!isExpanded)}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        role="button"
        tabIndex={0}
        aria-expanded={isExpanded}
        aria-label={`Rule ${ruleId}: ${ruleElement}. Click to ${isExpanded ? 'collapse' : 'expand'}`}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            setIsExpanded(!isExpanded);
          }
        }}
      >
        {renderOuterRow()}
      </div>

      {/* Inner Content (Expanded State) - CSS Grid Animation */}
      <div
        style={{
          display: 'grid',
          gridTemplateRows: isExpanded ? '1fr' : '0fr',
          transition: `grid-template-rows ${duration}ms cubic-bezier(0.4, 0, 0.2, 1)`,
        }}
      >
        <div style={{ overflow: 'hidden' }}>
          {renderInnerContent()}
        </div>
      </div>
    </div>
  );
}

